      icon: Settings,
      path: "/student/settings",
    },
  ],

  teacher: [
    {
      label: "Dashboard",
      icon: LayoutDashboard,
      path: "/teacher/dashboard",
    },
    {
      label: "Courses",
      icon: BookOpen,
      path: "/teacher/courses",
    },
    {
      label: "Quizzes",
      icon: GraduationCap,
      path: "/teacher/quizzes",
    },
    {
      label: "Assignments",
      icon: ClipboardList,
      path: "/teacher/assignments",
    },
    {
      label: "Notes Hub",
      icon: FileText,
      path: "/teacher/notes",
    },
    {
      label: "Calendar",
      icon: Calendar,
      path: "/teacher/calendar",
    },
    {
      label: "Manage Schedule",
      icon: Clock,
      path: "/teacher/schedule-manager",
    },
    {
