          <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary text-primary-content shadow-lg">

            <GraduationCap className="h-6 w-6" />

          </div>

          {/* LOGO TEXT */}
          {!isCollapsed && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
            >

              <h1 className="text-xl font-bold text-base-content">
                LMS Pro
              </h1>

              <p className="text-xs text-base-content/60 capitalize">
                {role.replace("_", " ")}
              </p>

            </motion.div>
          )}

        </div>

        {/* MOBILE CLOSE */}
        <button
          onClick={onMobileClose}
          className="btn btn-ghost btn-sm lg:hidden"
        >
          <X className="h-5 w-5" />
        </button>

      </div>

      {/* NAVIGATION */}
      <div className="flex-1 overflow-y-auto px-3 py-5">

        <ul className="menu gap-2">

          {navItems.map((item) => {
            const isActive =
              location.pathname === item.path;

            return (
              <li key={item.path}>

                <NavLink
                  to={item.path}
                  className={cn(
                    "group relative flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium transition-all duration-300",
                    isActive
                      ? "bg-primary text-primary-content shadow-md"
                      : "hover:bg-base-200 text-base-content/70 hover:text-base-content"
                  )}
                >

                  {/* ACTIVE INDICATOR */}
                  {isActive && (
                    <motion.div
                      layoutId="active-pill"
                      className="absolute inset-0 rounded-2xl bg-primary"
                      transition={{
                        type: "spring",
                        stiffness: 300,
                        damping: 30,
                      }}
                    />
                  )}

                  {/* ICON */}
                  <item.icon
                    className={cn(
                      "relative z-10 h-5 w-5 shrink-0",
                      isCollapsed &&
                        "mx-auto"
                    )}
                  />

                  {/* LABEL */}
                  {!isCollapsed && (
                    <span className="relative z-10">
                      {item.label}
                    </span>
                  )}

                </NavLink>

              </li>
            );
          })}

        </ul>

      </div>

      {/* BOTTOM NAV */}
      <div className="border-t border-base-300 px-3 py-4">

        <ul className="menu gap-2">

          {bottomNavItems.map((item) => {
            const isActive =
              location.pathname === item.path;

            return (
              <li key={item.path}>

                <NavLink
                  to={item.path}
                  className={cn(
                    "flex items-center gap-3 rounded-2xl px-4 py-3 text-sm font-medium transition-all duration-300",
                    isActive
                      ? "bg-secondary text-secondary-content"
                      : "hover:bg-base-200 text-base-content/70 hover:text-base-content"
                  )}
                >

                  <item.icon
                    className={cn(
                      "h-5 w-5",
                      isCollapsed &&
                        "mx-auto"
                    )}
                  />

                  {!isCollapsed && (
                    <span>{item.label}</span>
                  )}

                </NavLink>

              </li>
            );
          })}

        </ul>

      </div>

      {/* COLLAPSE BUTTON */}
      <div className="hidden border-t border-base-300 p-4 lg:block">

        <button
          onClick={onToggle}
          className="btn btn-outline btn-sm w-full rounded-xl"
        >

          {isCollapsed ? (
            <ChevronRight className="h-4 w-4" />
          ) : (
            <>
              <ChevronLeft className="h-4 w-4" />
              Collapse
            </>
          )}

        </button>

      </div>

    </div>
  );

  return (
    <>
      {/* MOBILE OVERLAY */}
      <AnimatePresence>

        {isMobileOpen && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onMobileClose}
            className="fixed inset-0 z-40 bg-black/50 backdrop-blur-sm lg:hidden"
          />
        )}

      </AnimatePresence>

      {/* MOBILE SIDEBAR */}
      <motion.aside
        initial={{ x: -320 }}
        animate={{
          x: isMobileOpen ? 0 : -320,
        }}
        transition={{
          type: "spring",
          stiffness: 260,
          damping: 25,
        }}
        className="fixed left-0 top-0 z-50 h-screen w-72 border-r border-base-300 shadow-2xl lg:hidden"
      >

        <SidebarContent />

      </motion.aside>

      {/* DESKTOP SIDEBAR */}
      <aside
        className={cn(
          "fixed left-0 top-0 z-30 hidden h-screen flex-col border-r border-base-300 bg-base-100 shadow-sm transition-all duration-300 lg:flex",
          isCollapsed
            ? "w-24"
            : "w-72"
        )}
      >

        <SidebarContent />

      </aside>
    </>
  );
}

export default Sidebar;

import React from "react";
import { Navigate, useLocation } from "react-router-dom";

import { useAuth } from "../../context/AuthContext";

// ============================================
// ROLE REDIRECTS
// ============================================
const roleRedirects = {
  super_admin: "/admin/dashboard",
  teacher: "/teacher/dashboard",
  student: "/student/dashboard",
};

// ============================================
// LOADING SCREEN
// ============================================
function LoadingScreen() {
  return (
    <div className="flex min-h-screen items-center justify-center bg-base-200">

      <div className="card w-80 bg-base-100 shadow-2xl">

        <div className="card-body items-center text-center">

          {/* LOADER */}
          <span className="loading loading-spinner loading-lg text-primary"></span>

          <h2 className="mt-4 text-xl font-bold text-base-content">
            Checking Access
          </h2>

          <p className="text-sm text-base-content/60">
            Please wait while we verify your account
          </p>

        </div>

      </div>

    </div>
  );
}

// ============================================
// ACCESS DENIED
// ============================================
function AccessDenied({ redirectPath }) {
  return (
    <div className="flex min-h-screen items-center justify-center bg-base-200 p-4">

      <div className="card w-full max-w-md border border-error/20 bg-base-100 shadow-2xl">

        <div className="card-body text-center">

          {/* ICON */}
          <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-error/10">

            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-10 w-10 text-error"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >

              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 9v2m0 4h.01M5.07 19h13.86c1.54 0 2.5-1.67 1.73-3L13.73 4c-.77-1.33-2.69-1.33-3.46 0L3.34 16c-.77 1.33.19 3 1.73 3z"
              />

            </svg>

          </div>

          {/* TEXT */}
          <h2 className="text-2xl font-bold text-base-content">
            Access Denied
          </h2>

          <p className="mt-2 text-sm text-base-content/60">
            You do not have permission to access this page.
          </p>

          {/* BUTTON */}
          <div className="mt-6">

            <a
              href={redirectPath}
              className="btn btn-primary w-full rounded-xl"
            >
              Go To Dashboard
            </a>

          </div>

        </div>

      </div>

    </div>
  );
}

// ============================================
// ROLE GUARD
// ============================================
export default function RoleGuard({
  children,
  allowedRoles = [],
}) {
  const {
    isAuthenticated,
    role,
    isLoading,
  } = useAuth();

  const location = useLocation();

  // ============================================
  // LOADING
  // ============================================
  if (isLoading) {
    return <LoadingScreen />;
  }

  // ============================================
  // NOT AUTHENTICATED
  // ============================================
  if (!isAuthenticated) {
    return (
      <Navigate
        to="/login"
        replace
        state={{
          from: location,
        }}
      />
    );
  }

  // ============================================
  // INVALID ROLE
  // ============================================
  if (
    allowedRoles.length > 0 &&
    !allowedRoles.includes(role)
  ) {
    return (
      <AccessDenied
        redirectPath={
          roleRedirects[role] ||
          "/login"
        }
      />
    );
  }

  // ============================================
  // SUCCESS
  // ============================================
  return <>{children}</>;
}

import React from "react";
import { cn } from "../../utils/cn";

export function Avatar({ className, size = "md", ...props }) {
  const sizes = {
    sm: "h-8 w-8",
    md: "h-10 w-10",
    lg: "h-12 w-12",
    xl: "h-16 w-16",
  };

  return (
    <div
      className={cn(
        "relative flex shrink-0 overflow-hidden rounded-full",
        sizes[size],
        className
      )}
      {...props}
    />
  );
}

export function AvatarImage({ src, alt, className, ...props }) {
  return (
    <img
