            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          </button>
        </div>
      </div>

      {/* Filters */}
      <FilterSystem onFilterChange={handleFilterChange} />

      {/* Analytics Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-4 gap-6">
