          title="Avg Quiz Accuracy"
          value={`${data?.metrics?.avgQuizAccuracy ?? 0}%`}
          trendValue="Strong aggregate"
          trendDirection="up"
          color="blue"
          icon={HelpCircle}
          loading={loading}
        />
        <AnalyticsCard
          title="Passing Ratio"
          value={`${data?.metrics?.passRate ?? 0}%`}
          trendValue="Target 80% passing"
          trendDirection="up"
          color="emerald"
          icon={CheckCircle2}
          loading={loading}
        />
        <AnalyticsCard
          title="Assignment Submissions"
          value={data?.metrics?.totalSubmissions ?? 0}
          trendValue="Graded/Pending"
          trendDirection="up"
          color="purple"
          icon={FileCheck}
          loading={loading}
        />
