      text: "font-sans text-slate-900",
      accent: "text-indigo-600",
    },
    {
      name: "Premium",
      desc: "Vibrant details, gold seals, and sleek glass details.",
      border: "border-[12px] border-amber-500/20",
      bg: "bg-amber-50/10",
      text: "font-serif text-slate-800",
      accent: "text-amber-600",
    },
