import {
  GraduationCap,
  Eye,
  EyeOff,
  Loader2,
  Sparkles,
  Mail,
  Lock,
  ArrowRight,
  Shield,
  Zap,
} from "lucide-react";

import { useAuth } from "../../context/AuthContext";

// =====================================
// DEMO USERS
