                    required
                    className="w-full pl-11 pr-12 py-3 rounded-xl text-sm text-white placeholder-slate-500 transition-all duration-200 focus:outline-none"
                    style={{
                      background: "rgba(15,23,42,0.8)",
                      border: "1px solid rgba(201,162,39,0.2)",
