import { motion, AnimatePresence } from "framer-motion";

const GOLD = "#C9A227";
const GOLD_LIGHT = "#F59E0B";

// ─── Duration formatter ───────────────────────────────
function formatDuration(start, end) {
  const ms = new Date(end) - new Date(start);
  const mins = Math.round(ms / 60000);
  if (mins < 60) return `${mins}m`;
  return `${Math.floor(mins / 60)}h ${mins % 60}m`;
}

// ─── Countdown Timer ──────────────────────────────────
function CountdownBadge({ startDate }) {
  const [timeLeft, setTimeLeft] = useState("");

  useEffect(() => {
    const update = () => {
      const diff = new Date(startDate) - new Date();
      if (diff <= 0) { setTimeLeft("Starting now!"); return; }
      const h = Math.floor(diff / 3600000);
      const m = Math.floor((diff % 3600000) / 60000);
      const s = Math.floor((diff % 60000) / 1000);
      if (h > 0) setTimeLeft(`${h}h ${m}m`);
      else if (m > 0) setTimeLeft(`${m}m ${s}s`);
      else setTimeLeft(`${s}s`);
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, [startDate]);

  return (
    <span className="text-[9px] font-black uppercase tracking-widest px-2.5 py-1 rounded-full flex items-center gap-1"
      style={{ background: "rgba(201,162,39,0.15)", color: GOLD, border: "1px solid rgba(201,162,39,0.25)" }}>
      <Zap className="h-3 w-3" />
      {timeLeft}
    </span>
  );
}

// ═══════════════════════════════════════════════════════
// MAIN COMPONENT
// ═══════════════════════════════════════════════════════
export default function LiveClasses() {
  const navigate = useNavigate();
  const user = getStoredUser();
  const [classes, setClasses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState("all"); // all | live | upcoming | past

  const loadClasses = async () => {
    try {
      setLoading(true);
      const res = await getCalendarEvents();
      // apiGet returns Axios response → payload is in res.data
      const payload = res?.data ?? res;
      if (payload?.success !== false) {
        const liveOnly = (payload?.data || []).filter((e) => e.type === "class");
        setClasses(liveOnly);
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadClasses(); }, []);

  const now = new Date();
  const isLive = (cls) =>
    now >= new Date(cls.startDate) && now <= new Date(cls.endDate);
  const isUpcoming = (cls) => new Date(cls.startDate) > now;
  const isPast = (cls) => new Date(cls.endDate) < now;

  const liveNow = classes.filter(isLive);
  const upcoming = classes.filter(isUpcoming);
  const past = classes.filter(isPast);

  const filteredClasses =
    filter === "live" ? liveNow
    : filter === "upcoming" ? upcoming
    : filter === "past" ? past
    : classes;

