            {liveNow.length > 0 && (
              <span className="absolute -top-1 -right-1 w-4 h-4 rounded-full border-2 animate-pulse"
                style={{ background: "#34D399", borderColor: "#0F172A" }} />
            )}
          </div>
          <div>
            <h1 className="text-2xl font-black text-white tracking-tight">
              Live <span style={{ color: GOLD }}>Classrooms</span>
            </h1>
            <p className="text-slate-500 text-xs mt-0.5">
              Join scheduled Zoom/Meet sessions and video lectures.
            </p>
          </div>
        </div>

        <div className="flex items-center gap-3 flex-wrap">
          {/* Live count badge */}
          {liveNow.length > 0 && (
