import React, { useState, useEffect, useCallback } from "react";
import { motion } from "framer-motion";
import {
  Calendar, CheckCircle, XCircle, Clock, Plane, Filter, RefreshCw, FileText
} from "lucide-react";
import { Card, CardContent } from "../../../components/ui/Card";
import { Input } from "../../../components/ui/Input";
import { Badge } from "../../../components/ui/Badge";
import { Button } from "../../../components/ui/Button";
import { getMyAttendance } from "../../../services/attendanceService";
import toast from "react-hot-toast";

const STATUS_CONFIG = {
  present: { label: "Present", color: "#10b981", cls: "bg-emerald-500/10 text-emerald-600 border-emerald-500/20", icon: CheckCircle },
  absent:  { label: "Absent",  color: "#f43f5e", cls: "bg-red-500/10 text-red-500 border-red-500/20",           icon: XCircle   },
  late:    { label: "Late",    color: "#f59e0b", cls: "bg-amber-500/10 text-amber-600 border-amber-500/20",     icon: Clock     },
  leave:   { label: "Leave",   color: "#3b82f6", cls: "bg-blue-500/10 text-blue-500 border-blue-500/20",        icon: Plane     },
};

export default function AttendanceHistory() {
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [filterCourse, setFilterCourse] = useState("");

  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      const res = await getMyAttendance({ from, to, courseId: filterCourse });
      if (res.data?.success) {
        setRecords(res.data.data || []);
      }
    } catch {
      toast.error("Failed to load attendance history");
    } finally {
      setLoading(false);
    }
  }, [from, to, filterCourse]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleExport = () => {
    if (records.length === 0) {
      toast.error("No records to export");
      return;
    }
    const headers = "Date,Course,Status,Remarks\n";
    const rows = records
      .map(
        (r) =>
          `"${new Date(r.date).toLocaleDateString()}",` +
          `"${r.courseId?.title || "Unknown"}",` +
          `"${r.status.toUpperCase()}",` +
          `"${r.remarks || ""}"`
      )
      .join("\n");

    const blob = new Blob([headers + rows], { type: "text/csv" });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.setAttribute("href", url);
    a.setAttribute("download", "Attendance_History.csv");
    a.click();
    toast.success("Exported successfully");
  };

  const formatDate = (d) =>
    new Date(d).toLocaleDateString("en-US", {
      weekday: "short",
      year: "numeric",
      month: "short",
      day: "numeric",
    });

  return (
    <div className="space-y-6 max-w-6xl mx-auto" id="attendance-history-page">
