            <Button onClick={loadData} disabled={loading} className="bg-indigo-600 hover:bg-indigo-700 text-white h-10">
              <Filter className="h-4 w-4 mr-2" />
              Filter Records
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Records Grid/Table */}
