                records.map((record, idx) => {
                  const cfg = STATUS_CONFIG[record.status] || STATUS_CONFIG.present;
                  return (
                    <motion.tr
                      key={record._id}
                      initial={{ opacity: 0 }}
                      animate={{ opacity: 1 }}
                      transition={{ delay: idx * 0.02 }}
