                        </div>
                        <PercentageMeter percentage={course.percentage} status={course.status} />
                      </motion.div>
                    ))
                  )}
                </div>
              </Card>
            </div>
          </div>
        </div>
      )}

      {/* ── HISTORY TAB ── */}
      {tab === "history" && (
