        </div>
      </div>

      {/* Top 3 Podiums Showcase */}
      {leaderboard.length >= 3 && !loading && (
        <div className="grid grid-cols-3 gap-4 max-w-2xl mx-auto pt-6 items-end">
          {/* Podium 2nd */}
          <div className="flex flex-col items-center space-y-3">
            <div className="relative">
              <div className="h-16 w-16 rounded-full border-2 border-slate-300 bg-neutral-800 flex items-center justify-center font-black text-slate-300 text-xl shadow">
                {leaderboard[1].name.substring(0, 2).toUpperCase()}
              </div>
              <span className="absolute -bottom-1 -right-1 h-6 w-6 rounded-full bg-slate-400 text-neutral-950 border-2 border-neutral-900 flex items-center justify-center font-bold text-xs">
                2
              </span>
            </div>
            <div className="w-full rounded-t-xl bg-slate-300/10 border border-slate-300/25 p-4 text-center space-y-1 h-28">
              <p className="text-xs font-black text-white truncate">{leaderboard[1].name}</p>
              <p className="text-[10px] text-slate-300 font-bold">{leaderboard[1].avgAccuracy}% Acc</p>
              <span className="text-[9px] text-white/40 block mt-1 font-semibold">{leaderboard[1].completedCourses} Finished</span>
            </div>
          </div>

          {/* Podium 1st (Crown) */}
          <div className="flex flex-col items-center space-y-3">
            <div className="relative">
              <Crown className="absolute -top-7 left-1/2 -translate-x-1/2 h-7 w-7 text-amber-400 animate-bounce" />
              <div className="h-20 w-20 rounded-full border-4 border-amber-500 bg-neutral-800 flex items-center justify-center font-black text-amber-500 text-2xl shadow-xl shadow-amber-500/10">
                {leaderboard[0].name.substring(0, 2).toUpperCase()}
              </div>
              <span className="absolute -bottom-1 -right-1 h-7 w-7 rounded-full bg-amber-500 text-neutral-950 border-2 border-neutral-900 flex items-center justify-center font-black text-xs">
                1
              </span>
            </div>
            <div className="w-full rounded-t-2xl bg-amber-500/15 border border-amber-500/25 p-4 text-center space-y-1 h-36">
              <p className="text-sm font-black text-white truncate">{leaderboard[0].name}</p>
              <p className="text-xs text-amber-400 font-black">{leaderboard[0].avgAccuracy}% Acc</p>
              <span className="text-[10px] text-white/50 block mt-1 font-semibold">{leaderboard[0].completedCourses} Finished</span>
            </div>
          </div>

          {/* Podium 3rd */}
          <div className="flex flex-col items-center space-y-3">
            <div className="relative">
              <div className="h-14 w-14 rounded-full border-2 border-amber-700 bg-neutral-800 flex items-center justify-center font-black text-amber-700 text-lg shadow">
                {leaderboard[2].name.substring(0, 2).toUpperCase()}
              </div>
              <span className="absolute -bottom-1 -right-1 h-5 w-5 rounded-full bg-amber-700 text-neutral-950 border-2 border-neutral-900 flex items-center justify-center font-bold text-xs">
                3
              </span>
            </div>
            <div className="w-full rounded-t-xl bg-amber-700/10 border border-amber-700/25 p-4 text-center space-y-1 h-24">
              <p className="text-xs font-black text-white truncate">{leaderboard[2].name}</p>
              <p className="text-[10px] text-amber-600 font-bold">{leaderboard[2].avgAccuracy}% Acc</p>
              <span className="text-[9px] text-white/40 block mt-1 font-semibold">{leaderboard[2].completedCourses} Finished</span>
            </div>
          </div>
        </div>
      )}

      {/* Ranks Directory Table */}
      <div className="rounded-2xl border border-white/10 bg-black/40 overflow-hidden backdrop-blur-xl">
        <div className="p-6 border-b border-white/5">
          <h3 className="text-sm font-semibold tracking-wider text-white/50 uppercase">
            Leaderboards Leaderboards
          </h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm text-white/80">
            <thead className="bg-white/5 text-xs text-white/40 uppercase tracking-wider">
              <tr>
                <th className="py-3 px-6 text-center">Rank</th>
                <th className="py-3 px-6">Student name</th>
                <th className="py-3 px-6">Student email</th>
                <th className="py-3 px-6 text-center">Average Accuracy</th>
                <th className="py-3 px-6 text-center">Quizzes Taken</th>
                <th className="py-3 px-6 text-center">Completed Courses</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {loading ? (
                <tr>
                  <td colSpan="6" className="py-8 text-center text-white/30">Loading leaderboards...</td>
                </tr>
              ) : leaderboard.length === 0 ? (
                <tr>
                  <td colSpan="6" className="py-8 text-center text-white/30">No active student rankings recorded.</td>
                </tr>
              ) : (
                leaderboard.map((student, index) => (
                  <tr key={index} className="hover:bg-white/5 transition-colors">
                    <td className="py-4 px-6 text-center">
                      <span className={`h-6 w-6 rounded-full flex items-center justify-center font-bold text-xs mx-auto ${
                        index === 0
                          ? "bg-amber-500/20 text-amber-400 border border-amber-500/30"
                          : index === 1
                          ? "bg-slate-300/20 text-slate-300 border border-slate-300/30"
                          : index === 2
                          ? "bg-amber-700/20 text-amber-600 border border-amber-700/30"
                          : "bg-white/5 text-white/60"
                      }`}>
                        {index + 1}
                      </span>
                    </td>
                    <td className="py-4 px-6 font-semibold text-white">{student.name}</td>
                    <td className="py-4 px-6 text-white/50">{student.email}</td>
                    <td className="py-4 px-6 text-center font-black text-emerald-400">{student.avgAccuracy}%</td>
                    <td className="py-4 px-6 text-center text-white/60">{student.quizzesAttempted}</td>
                    <td className="py-4 px-6 text-center font-semibold text-purple-400">{student.completedCourses} courses</td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import {
  Search, Send, Paperclip, Image, MoreVertical,
  MessageSquare, CheckCheck, Clock, User, Phone, Mail, PlusCircle, Check
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../../components/ui/Card";
import { Badge } from "../../../components/ui/Badge";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { Avatar, AvatarImage, AvatarFallback } from "../../../components/ui/Avatar";
import { EmptyState } from "../../../components/ui/EmptyState";
import { useAuth } from "../../../context/AuthContext";
import { useSocket } from "../../../context/SocketContext";
import { apiGet, apiPost, apiPatch } from "../../../services/apiClient";
import toast from "react-hot-toast";

const container = { hidden: { opacity: 0 }, show: { opacity: 1, transition: { staggerChildren: 0.05 } } };
const item = { hidden: { opacity: 0, y: 20 }, show: { opacity: 1, y: 0 } };

export default function Messages() {
  const { user: currentUser } = useAuth();
  const { socket, isConnected, onlineUsers } = useSocket();

  const [conversations, setConversations] = useState([]);
  const [selectedConv, setSelectedConv] = useState(null);
  const [messages, setMessages] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [messageText, setMessageText] = useState("");
  const [loadingConvs, setLoadingConvs] = useState(true);
  const [loadingMessages, setLoadingMessages] = useState(false);

  // New Chat fields
  const [showNewChatModal, setShowNewChatModal] = useState(false);
  const [availableContacts, setAvailableContacts] = useState([]);
  const [loadingContacts, setLoadingContacts] = useState(false);

  // Typing state
  const [partnerTyping, setPartnerTyping] = useState(false);
  const typingTimeoutRef = useRef(null);
  const isTypingRef = useRef(false);

  const chatEndRef = useRef(null);

  // Scroll to bottom of chat
  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, partnerTyping]);

  // Load all active conversations
  const loadConversations = async () => {
    try {
      setLoadingConvs(true);
      const res = await apiGet("/messages/conversations");
      if (res.data?.success) {
        setConversations(res.data.data || []);
      }
    } catch (err) {
      console.error("Failed to load conversations:", err);
    } finally {
      setLoadingConvs(false);
    }
  };

  useEffect(() => {
    loadConversations();
  }, []);

  // Load messages for the selected conversation
  const loadMessages = async (partnerId) => {
    try {
      setLoadingMessages(true);
      const res = await apiGet(`/messages/${partnerId}`);
      if (res.data?.success) {
        setMessages(res.data.data || []);
      }
    } catch (err) {
      console.error("Failed to load messages:", err);
    } finally {
      setLoadingMessages(false);
    }
  };

  // Select a conversation and mark as read
  const handleSelectConversation = async (conv) => {
    setSelectedConv(conv);
    const partnerId = conv.participant._id;
    await loadMessages(partnerId);

    // Call API to mark as read
    try {
      await apiPatch(`/messages/read/${partnerId}`);
      // Decrement unread counts locally
      setConversations((prev) =>
        prev.map((c) =>
          c.participant._id === partnerId ? { ...c, unreadCount: 0 } : c
        )
      );
    } catch (err) {
      console.error("Failed to mark messages as read:", err);
    }
  };

  // Live Socket Event Handlers
  useEffect(() => {
    if (!socket) return;

    // 1. Receive fresh messages
    const handleNewMessage = (msg) => {
      // Determine other party's ID in this message
      const senderId = typeof msg.senderId === "object" ? msg.senderId._id : msg.senderId;
      const recipientId = typeof msg.recipientId === "object" ? msg.recipientId._id : msg.recipientId;

      const otherPartyId = senderId === currentUser.id ? recipientId : senderId;

      // Case A: Message belongs to currently open conversation
      if (selectedConv && selectedConv.participant._id === otherPartyId) {
        setMessages((prev) => [...prev, msg]);

        // Mark as read instantly on the backend
        if (senderId !== currentUser.id) {
          apiPatch(`/messages/read/${otherPartyId}`).catch(console.error);
        }
      }

      // Case B: Update the lastMessage and unread count in conversations sidebar
      setConversations((prev) => {
        const index = prev.findIndex((c) => c.participant._id === otherPartyId);
        const updated = [...prev];

        if (index !== -1) {
          // Update existing conversation
          updated[index] = {
            ...updated[index],
            lastMessage: msg,
            unreadCount:
              selectedConv && selectedConv.participant._id === otherPartyId
                ? 0
                : senderId !== currentUser.id
                ? updated[index].unreadCount + 1
                : 0,
          };
        } else {
          // Fetch conversations list again to register the new contact
          loadConversations();
        }
        return updated;
      });
    };

    // 2. Outbound message confirmation
    const handleMessageSent = (msg) => {
      // Handled by handleNewMessage or API response safely
    };

    // 3. Read status receipts
    const handleMessagesRead = ({ readerId }) => {
      if (selectedConv && selectedConv.participant._id === readerId) {
        setMessages((prev) =>
          prev.map((m) => (m.senderId._id === currentUser.id || m.senderId === currentUser.id ? { ...m, read: true } : m))
        );
      }
    };

    // 4. Partner Typing indicator
    const handleUserTyping = ({ userId }) => {
      if (selectedConv && selectedConv.participant._id === userId) {
        setPartnerTyping(true);
      }
    };

    const handleUserStopTyping = ({ userId }) => {
      if (selectedConv && selectedConv.participant._id === userId) {
        setPartnerTyping(false);
      }
    };

    socket.on("new-message", handleNewMessage);
    socket.on("message-sent", handleMessageSent);
    socket.on("messages-read", handleMessagesRead);
    socket.on("user-typing", handleUserTyping);
    socket.on("user-stop-typing", handleUserStopTyping);

    return () => {
      socket.off("new-message", handleNewMessage);
      socket.off("message-sent", handleMessageSent);
      socket.off("messages-read", handleMessagesRead);
      socket.off("user-typing", handleUserTyping);
      socket.off("socket-stop-typing", handleUserStopTyping);
    };
  }, [socket, selectedConv, currentUser]);

  // Send message controller
  const sendMessage = async () => {
    if (!messageText.trim() || !selectedConv) return;
    const partnerId = selectedConv.participant._id;

    // Stop typing signal immediately
    if (isTypingRef.current) {
      socket?.emit("typing-stop", { recipientId: partnerId });
      isTypingRef.current = false;
    }

    try {
      const res = await apiPost("/messages", {
        recipientId: partnerId,
        content: messageText,
      });

      if (res.data?.success) {
        const newMsg = res.data.data;
        setMessages((prev) => [...prev, newMsg]);

        // Update sidebar conversation item
        setConversations((prev) =>
          prev.map((c) =>
            c.participant._id === partnerId
              ? { ...c, lastMessage: newMsg, unreadCount: 0 }
              : c
          )
        );
        setMessageText("");
      }
    } catch (err) {
      toast.error("Failed to send message");
    }
  };

  // Keyboard typing handlers
  const handleInputChange = (e) => {
    setMessageText(e.target.value);
    if (!socket || !selectedConv) return;

    const partnerId = selectedConv.participant._id;

    if (!isTypingRef.current) {
      isTypingRef.current = true;
      socket.emit("typing-start", { recipientId: partnerId });
    }

    // Debounce the typing stop event
    if (typingTimeoutRef.current) clearTimeout(typingTimeoutRef.current);
    typingTimeoutRef.current = setTimeout(() => {
      socket.emit("typing-stop", { recipientId: partnerId });
      isTypingRef.current = false;
    }, 2000);
  };

  // Fetch student courses to find teachers to start new chat
  const handleOpenNewChatModal = async () => {
    setShowNewChatModal(true);
    try {
      setLoadingContacts(true);
      // Fetch student courses (which populate teachers!)
      const res = await apiGet("/student/courses");
      const courses = res.data || [];

      const teacherMap = new Map();
      courses.forEach((c) => {
        if (c.teacherId) {
          teacherMap.set(c.teacherId._id, c.teacherId);
        }
      });

      // Include Support contact as a default option
      const supportContact = {
        _id: "support-agent-id-placeholder",
        name: "LMS Pro Support Team",
        role: "Support",
        avatar: "",
      };

      setAvailableContacts([
        supportContact,
        ...Array.from(teacherMap.values()).map((t) => ({ ...t, role: "Instructor" })),
      ]);
    } catch (err) {
      console.error("Failed to load contacts:", err);
    } finally {
      setLoadingContacts(false);
    }
  };

  const handleStartChatWithContact = (contact) => {
    // Check if conversation already exists
    const existing = conversations.find(
      (c) => c.participant._id === contact._id
    );

    if (existing) {
      handleSelectConversation(existing);
    } else {
      // Mock conversation item in UI
      const mockConv = {
        participant: contact,
        lastMessage: { content: "Start of your new chat history.", createdAt: new Date() },
        unreadCount: 0,
      };
      setConversations((prev) => [mockConv, ...prev]);
      setSelectedConv(mockConv);
      setMessages([]);
    }
    setShowNewChatModal(false);
  };

  const filteredConvs = conversations.filter((c) =>
    c.participant?.name?.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <motion.div variants={container} initial="hidden" animate="show" className="h-[calc(100vh-8rem)] flex gap-6">
      {/* Conversations List */}
      <motion.div variants={item} className="w-80 flex flex-col shrink-0">
        <Card className="h-full flex flex-col overflow-hidden border-muted shadow-lg">
          <CardHeader className="p-4 border-b flex flex-col gap-3">
            <div className="flex items-center justify-between">
              <h2 className="font-semibold text-lg flex items-center gap-2">
                <MessageSquare className="h-5 w-5 text-primary" /> Messages
              </h2>
              <Button size="icon" variant="ghost" className="text-primary hover:bg-primary/10 rounded-full" onClick={handleOpenNewChatModal}>
                <PlusCircle className="h-5 w-5" />
              </Button>
            </div>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
              <Input className="pl-9 h-9 border-muted" placeholder="Search chats..." value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
            </div>
          </CardHeader>
          <div className="flex-1 overflow-y-auto">
            {loadingConvs ? (
              <div className="flex flex-col items-center justify-center h-48 space-y-2">
                <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary border-t-transparent" />
                <p className="text-xs text-muted-foreground">Loading active chats...</p>
              </div>
            ) : filteredConvs.length === 0 ? (
              <div className="p-6 text-center text-sm text-muted-foreground flex flex-col items-center gap-2">
                <p>No active conversations</p>
                <Button size="sm" variant="outline" className="mt-2" onClick={handleOpenNewChatModal}>
                  Start Chatting
                </Button>
              </div>
            ) : (
              filteredConvs.map((conv) => {
                const isUserOnline = onlineUsers.has(conv.participant?._id) || conv.participant?.isOnline;
                return (
                  <button
                    key={conv.participant?._id}
                    onClick={() => handleSelectConversation(conv)}
                    className={`w-full flex items-start gap-3 p-4 hover:bg-primary/5 transition-all text-left border-b border-muted/50 ${selectedConv?.participant?._id === conv.participant?._id ? "bg-primary/10 border-l-4 border-l-primary" : ""}`}
                  >
                    <div className="relative shrink-0">
                      <Avatar className="w-10 h-10 border border-muted">
                        <AvatarImage src={conv.participant?.avatar} />
                        <AvatarFallback className="bg-primary/20 text-primary">{conv.participant?.name?.charAt(0)}</AvatarFallback>
                      </Avatar>
                      {isUserOnline && (
                        <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 rounded-full border-2 border-background shadow-sm" />
                      )}
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center">
                        <p className="font-medium text-sm truncate">{conv.participant?.name}</p>
                        <p className="text-[10px] text-muted-foreground shrink-0">
                          {conv.lastMessage?.createdAt ? new Date(conv.lastMessage.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ""}
                        </p>
                      </div>
                      <p className={`text-xs truncate mt-1 ${conv.unreadCount > 0 ? "font-semibold text-foreground" : "text-muted-foreground"}`}>
                        {conv.lastMessage?.content || "Tap to chat..."}
                      </p>
                    </div>
                    {conv.unreadCount > 0 && (
                      <div className="w-5 h-5 rounded-full bg-primary text-primary-foreground text-[10px] flex items-center justify-center shrink-0 font-bold ml-1 animate-pulse">
                        {conv.unreadCount}
                      </div>
                    )}
                  </button>
                );
              })
            )}
          </div>
        </Card>
      </motion.div>

      {/* Chat Window */}
      <motion.div variants={item} className="flex-1 flex flex-col">
        {selectedConv ? (
          <Card className="h-full flex flex-col overflow-hidden border-muted shadow-lg">
            {/* Chat Header */}
            <CardHeader className="p-4 border-b flex-row items-center gap-3 shrink-0">
              <div className="relative">
                <Avatar className="w-10 h-10 border">
                  <AvatarImage src={selectedConv.participant?.avatar} />
                  <AvatarFallback className="bg-primary/20 text-primary">{selectedConv.participant?.name?.charAt(0)}</AvatarFallback>
                </Avatar>
                {(onlineUsers.has(selectedConv.participant?._id) || selectedConv.participant?.isOnline) && (
                  <div className="absolute bottom-0 right-0 w-3 h-3 bg-emerald-500 rounded-full border-2 border-background" />
                )}
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-sm truncate">{selectedConv.participant?.name}</p>
                <p className="text-xs text-muted-foreground truncate">
                  {selectedConv.participant?.role || "Contact"} · {(onlineUsers.has(selectedConv.participant?._id) || selectedConv.participant?.isOnline) ? "Online" : "Offline"}
                </p>
              </div>
              <Button variant="ghost" size="icon" className="rounded-full"><MoreVertical className="h-4 w-4" /></Button>
            </CardHeader>

            {/* Messages body */}
            <div className="flex-1 overflow-y-auto p-4 space-y-4 bg-primary/5">
              {loadingMessages ? (
                <div className="flex flex-col items-center justify-center h-full space-y-2">
                  <div className="animate-spin rounded-full h-8 w-8 border-2 border-primary border-t-transparent" />
                  <p className="text-xs text-muted-foreground">Loading chat history...</p>
                </div>
              ) : messages.length === 0 ? (
                <div className="h-full flex flex-col items-center justify-center text-muted-foreground text-center p-6 space-y-2">
                  <MessageSquare className="h-10 w-10 text-primary/30" />
                  <p className="text-sm font-medium">Say hello!</p>
                  <p className="text-xs text-muted-foreground/80">Send a message to start the conversation.</p>
                </div>
              ) : (
                messages.map((msg) => {
                  const isMe = (msg.senderId?._id || msg.senderId) === currentUser.id;
                  const senderName = msg.senderId?.name || selectedConv.participant?.name;
                  return (
                    <div key={msg._id || Math.random()} className={`flex gap-2.5 ${isMe ? "justify-end" : ""}`}>
                      {!isMe && (
                        <Avatar className="w-8 h-8 border shrink-0">
                          <AvatarImage src={selectedConv.participant?.avatar} />
                          <AvatarFallback className="bg-primary/20 text-primary">{selectedConv.participant?.name?.charAt(0)}</AvatarFallback>
                        </Avatar>
                      )}
                      <div className={`max-w-[70%] ${isMe ? "order-1" : ""}`}>
                        <div className={`rounded-2xl px-4 py-2.5 shadow-sm text-sm ${isMe ? "bg-primary text-primary-foreground rounded-tr-none" : "bg-card border border-muted rounded-tl-none"}`}>
                          <p>{msg.content}</p>
                        </div>
                        <p className="text-[10px] text-muted-foreground mt-1 flex items-center justify-end gap-1 select-none">
                          {msg.createdAt && new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                          {isMe && (
                            <CheckCheck className={`h-3.5 w-3.5 ${msg.read ? "text-primary" : "text-muted-foreground"}`} />
                          )}
                        </p>
                      </div>
                    </div>
                  );
                })
              )}

              {/* Typing indicator bubble */}
              {partnerTyping && (
                <div className="flex gap-2.5 items-center">
                  <Avatar className="w-8 h-8 border shrink-0">
                    <AvatarImage src={selectedConv.participant?.avatar} />
                    <AvatarFallback className="bg-primary/20 text-primary">{selectedConv.participant?.name?.charAt(0)}</AvatarFallback>
                  </Avatar>
                  <div className="bg-card border border-muted px-4 py-2.5 rounded-2xl rounded-tl-none shadow-sm flex items-center space-x-1.5 h-9 shrink-0">
                    <span className="w-1.5 h-1.5 bg-primary rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                    <span className="w-1.5 h-1.5 bg-primary rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                    <span className="w-1.5 h-1.5 bg-primary rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                  </div>
                </div>
              )}
              <div ref={chatEndRef} />
            </div>

            {/* Input bar */}
            <div className="p-4 border-t bg-card shrink-0">
              <div className="flex items-center gap-2">
                <Button variant="ghost" size="icon" className="rounded-full hover:bg-primary/10 text-muted-foreground hover:text-primary"><Paperclip className="h-4 w-4" /></Button>
                <Button variant="ghost" size="icon" className="rounded-full hover:bg-primary/10 text-muted-foreground hover:text-primary"><Image className="h-4 w-4" /></Button>
                <Input
                  className="flex-1 border-muted focus-visible:ring-primary h-10 text-sm rounded-xl"
                  placeholder="Type your message..."
                  value={messageText}
                  onChange={handleInputChange}
                  onKeyDown={(e) => e.key === "Enter" && sendMessage()}
                />
                <Button
                  size="icon"
                  className="rounded-full h-10 w-10 shadow-md transition-all active:scale-95"
                  onClick={sendMessage}
                  disabled={!messageText.trim()}
                >
                  <Send className="h-4 w-4" />
                </Button>
              </div>
            </div>
          </Card>
        ) : (
          <EmptyState
            icon={MessageSquare}
            title="Your Inbox"
            description="Select a chat from the sidebar or start a new conversation with your instructor."
            action={{ label: "New Message", onClick: handleOpenNewChatModal }}
            className="h-full border border-muted shadow-lg"
          />
        )}
      </motion.div>

      {/* New Chat Modal Dialog overlay */}
      <AnimatePresence>
        {showNewChatModal && (
          <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
            <motion.div
              initial={{ scale: 0.95, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.95, opacity: 0 }}
              className="bg-card w-full max-w-md rounded-2xl border border-muted p-6 shadow-2xl flex flex-col max-h-[80vh] overflow-hidden"
            >
              <div className="flex justify-between items-center mb-4">
                <h3 className="font-semibold text-lg">New Conversation</h3>
                <Button variant="ghost" size="sm" onClick={() => setShowNewChatModal(false)}>Close</Button>
              </div>

              <div className="flex-1 overflow-y-auto space-y-2 mt-2">
                {loadingContacts ? (
                  <div className="flex flex-col items-center justify-center py-12 space-y-2">
                    <div className="animate-spin rounded-full h-6 w-6 border-2 border-primary border-t-transparent" />
                    <p className="text-xs text-muted-foreground">Loading instructors...</p>
                  </div>
                ) : availableContacts.length === 0 ? (
                  <p className="text-center text-sm text-muted-foreground py-8">No available contacts found.</p>
                ) : (
                  availableContacts.map((contact) => (
                    <button
                      key={contact._id}
                      onClick={() => handleStartChatWithContact(contact)}
                      className="w-full flex items-center gap-3 p-3 hover:bg-primary/5 rounded-xl transition-all text-left border border-muted/30"
                    >
                      <Avatar className="w-10 h-10 border">
                        <AvatarImage src={contact.avatar} />
                        <AvatarFallback className="bg-primary/20 text-primary">{contact.name.charAt(0)}</AvatarFallback>
                      </Avatar>
                      <div>
                        <p className="font-medium text-sm">{contact.name}</p>
                        <p className="text-xs text-muted-foreground">{contact.role}</p>
                      </div>
                    </button>
                  ))
                )}
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

import React, { useState, useEffect } from "react";
import { BookOpen, FileText, Download, HelpCircle, RefreshCw, Search } from "lucide-react";
import { getNotes } from "../../../services/notesService";
import { getCourses } from "../../../services/courseService";
import { useSocket } from "../../../context/SocketContext";
import { toast } from "react-hot-toast";

export default function MyNotes() {
  const { socket } = useSocket();
  const [courses, setCourses] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [notes, setNotes] = useState([]);
  const [loading, setLoading] = useState(false);
  const [search, setSearch] = useState("");

  useEffect(() => {
    async function loadCourses() {
      try {
        const res = await getCourses();
        if (res && res.success) {
          const list = Array.isArray(res.data) ? res.data : res.data?.courses || [];
          setCourses(list);
          if (list.length > 0) {
            setSelectedCourse(list[0]._id);
          }
        }
      } catch (err) {
        console.error(err);
      }
    }
    loadCourses();
  }, []);

  useEffect(() => {
    if (!selectedCourse) return;

    async function loadNotes() {
      try {
        setLoading(true);
        const res = await getNotes(selectedCourse);
        if (res && res.success) {
          setNotes(res.data || []);
        }
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    loadNotes();
  }, [selectedCourse]);

  useEffect(() => {
    if (!socket || !selectedCourse) return;

    const handleNoteCreated = (data) => {
      if (data.courseId === selectedCourse) {
        setNotes((prevNotes) => [data.note, ...prevNotes]);
        toast.success(`New Notes Published: "${data.note.title}"!`, { duration: 4000 });
      }
    };

    const handleNoteDeleted = (data) => {
      if (data.courseId === selectedCourse) {
        setNotes((prevNotes) => prevNotes.filter((n) => n._id !== data.noteId));
      }
    };

    socket.on("note-created", handleNoteCreated);
    socket.on("note-deleted", handleNoteDeleted);

    return () => {
      socket.off("note-created", handleNoteCreated);
      socket.off("note-deleted", handleNoteDeleted);
    };
  }, [socket, selectedCourse]);

  const filteredNotes = notes.filter(n =>
    n.title.toLowerCase().includes(search.toLowerCase()) ||
    n.content.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="space-y-6 max-w-7xl mx-auto p-4 sm:p-6 lg:p-8">
      {/* Header */}
      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-white/10 pb-5">
        <div>
          <h1 className="text-3xl font-extrabold text-white bg-gradient-to-r from-blue-400 to-indigo-400 bg-clip-text text-transparent">
            My Course Notes & Resources
          </h1>
          <p className="text-sm text-white/50 mt-1">Access rich summaries and download lecture resources uploaded by your teachers.</p>
        </div>
      </div>

      {/* Select Course and Search Bar */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* Selector */}
        <div className="rounded-xl border border-white/10 bg-black/20 px-3 py-2 flex items-center gap-2">
          <BookOpen className="h-4 w-4 text-white/50" />
          <select
            value={selectedCourse}
            onChange={(e) => setSelectedCourse(e.target.value)}
            className="w-full bg-transparent text-sm text-white focus:outline-none cursor-pointer"
          >
            {courses.map((course) => (
              <option key={course._id} value={course._id} className="bg-neutral-900 text-white">
                {course.title}
              </option>
            ))}
          </select>
        </div>

        {/* Search */}
        <div className="md:col-span-2 relative">
          <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-white/40" />
          <input
            type="text"
            placeholder="Search notes summaries..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full rounded-xl border border-white/10 bg-black/30 py-2.5 pl-10 pr-4 text-sm text-white focus:outline-none focus:border-blue-500/50"
          />
        </div>
      </div>

      {/* Notes Display */}
      {loading ? (
        <div className="py-12 flex items-center justify-center text-white/40 gap-2">
          <RefreshCw className="h-5 w-5 animate-spin" /> Loading classroom materials...
        </div>
      ) : filteredNotes.length === 0 ? (
        <div className="rounded-2xl border border-white/5 bg-white/5 p-12 text-center text-white/40 space-y-3">
          <FileText className="h-12 w-12 mx-auto text-white/20" />
          <p className="font-semibold text-white/60">No Notes Available</p>
          <p className="text-xs max-w-sm mx-auto">No study guides or summary outlines are uploaded for this course yet.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {filteredNotes.map((note) => (
            <div
              key={note._id}
              className="rounded-2xl border border-white/10 bg-black/40 p-6 shadow-2xl backdrop-blur-md flex flex-col justify-between"
            >
              <div className="space-y-3">
                <div className="flex items-center gap-2.5">
                  <div className="rounded-xl border border-blue-500/20 bg-blue-500/10 p-2 text-blue-400">
                    <FileText className="h-5 w-5" />
                  </div>
                  <div>
                    <h3 className="font-bold text-white leading-tight">{note.title}</h3>
                    <p className="text-[10px] text-white/40 font-semibold">Uploaded by: {note.teacherId?.name || "Instructor"}</p>
                  </div>
                </div>

                <div className="text-xs text-white/70 leading-relaxed font-medium bg-black/20 p-4 rounded-xl border border-white/5 max-h-40 overflow-y-auto whitespace-pre-wrap">
                  {note.content || "No summary text provided. Download the notes document attachment."}
                </div>
              </div>

              {note.fileUrl && (
                <div className="mt-5 border-t border-white/5 pt-4 flex items-center justify-between">
                  <span className="text-[10px] text-white/35 font-bold uppercase tracking-widest flex items-center gap-1">
                    <HelpCircle className="h-3.5 w-3.5" /> PDF Resource Attached
                  </span>
                  <a
                    href={note.fileUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="flex items-center gap-1.5 rounded-lg border border-blue-500/25 bg-blue-500/10 px-3 py-1.5 text-xs font-bold text-blue-400 hover:bg-blue-500/20 transition-all"
                  >
                    <Download className="h-3.5 w-3.5" /> Download Notes
                  </a>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// src/pages/student/quiz/Quiz.jsx

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";
import {
  HelpCircle,
  Clock,
  CheckCircle2,
  Calendar,
  BookOpen,
  Search,
  ChevronRight,
  Sparkles,
  AlertCircle,
  Award,
} from "lucide-react";

import { Card, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { Modal } from "../../../components/ui/Modal";
import { getQuizzes } from "../../../services/quizService";
import { getQuizAttempts } from "../../../services/attemptService";
import toast from "react-hot-toast";

const containerVariants = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: { staggerChildren: 0.05 },
  },
};

const itemVariants = {
  hidden: { opacity: 0, y: 15 },
  show: { opacity: 1, y: 0, transition: { type: "spring", stiffness: 100 } },
};

export default function StudentQuizList() {
  const navigate = useNavigate();
  const [quizzesList, setQuizzesList] = useState([]);
  const [searchQuery, setSearchQuery] = useState("");
  const [loading, setLoading] = useState(true);

  // Selected Quiz for instructions overlay
  const [selectedQuiz, setSelectedQuiz] = useState(null);
  const [attemptsHistory, setAttemptsHistory] = useState([]);
  const [loadingAttempts, setLoadingAttempts] = useState(false);

  useEffect(() => {
    async function loadQuizzes() {
      try {
        setLoading(true);
        const res = await getQuizzes();
        if (res.data?.success) {
          setQuizzesList(res.data.data || []);
        } else {
          toast.error("Failed to load active assessments");
        }
      } catch (err) {
        console.error("Error fetching quizzes:", err);
        toast.error("Error querying assessment logs from API");
      } finally {
        setLoading(false);
      }
    }
    loadQuizzes();
  }, []);

  const handleOpenInstructions = async (quiz) => {
    setSelectedQuiz(quiz);
    try {
      setLoadingAttempts(true);
      const res = await getQuizAttempts(quiz._id);
      if (res.data?.success) {
        setAttemptsHistory(res.data.data || []);
      }
    } catch (err) {
      console.error("Error fetching attempts history:", err);
    } finally {
      setLoadingAttempts(false);
    }
  };

  const handleStartAttempt = () => {
    if (!selectedQuiz) return;
    setSelectedQuiz(null);
    navigate(`/student/quizzes/attempt/${selectedQuiz._id}`);
  };

  const filteredQuizzes = quizzesList.filter((quiz) =>
    quiz.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
    (quiz.courseId?.title || "").toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="show"
      className="space-y-8"
      id="student-quizzes-dashboard"
    >
      {/* Header Panel */}
      <motion.div
        variants={itemVariants}
        className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between bg-gradient-to-r from-primary/10 via-base-100 to-base-100 p-6 rounded-3xl border border-primary/20 shadow-xl backdrop-blur-md"
      >
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <span className="badge badge-primary gap-1 py-3 px-3 rounded-full text-xs font-semibold">
              <Sparkles className="h-3 w-3 animate-pulse" /> Assessment Hub
            </span>
          </div>
          <h1 className="text-4xl font-extrabold tracking-tight text-foreground">Interactive Quizzes</h1>
          <p className="text-muted-foreground text-sm">
            Evaluate your knowledge base. Take course-wise exams, view grades, and unlock achievements.
          </p>
        </div>
      </motion.div>

      {/* Toolbar */}
      <motion.div
        variants={itemVariants}
        className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between bg-base-100 border border-base-300 p-4 rounded-2xl shadow-md"
      >
        <div className="relative w-full md:max-w-md">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search quizzes by title or course..."
            className="pl-11 h-12 bg-base-200 border-none rounded-2xl focus-visible:ring-2 focus-visible:ring-primary w-full text-sm"
            id="student-quizzes-search-field"
          />
        </div>
      </motion.div>

      {/* Quizzes List */}
      <motion.div variants={itemVariants} id="student-quizzes-list-panel">
        {loading ? (
          <div className="flex flex-col items-center justify-center py-20 gap-4">
            <div className="loading loading-spinner loading-lg text-primary"></div>
            <p className="text-sm text-muted-foreground animate-pulse font-medium">Fetching active assessments...</p>
          </div>
        ) : filteredQuizzes.length === 0 ? (
          <Card className="bg-base-100 shadow-xl border border-base-300 rounded-3xl" id="student-quizzes-empty-card">
            <CardContent className="py-20 text-center flex flex-col items-center max-w-md mx-auto">
              <div className="rounded-full bg-base-200 p-5 mb-5 text-muted-foreground">
                <HelpCircle className="h-10 w-10 text-muted-foreground/60" />
              </div>
              <h3 className="text-xl font-bold mb-2">No Quizzes Published</h3>
              <p className="text-muted-foreground text-sm mb-6">
                Your instructors have not published any exams or practice challenges for your enrolled courses yet.
              </p>
            </CardContent>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6" id="student-quizzes-grid">
            {filteredQuizzes.map((quiz) => (
              <motion.div
                key={quiz._id}
                whileHover={{ y: -3 }}
                transition={{ type: "spring", stiffness: 300, damping: 20 }}
                className="cursor-pointer"
                onClick={() => handleOpenInstructions(quiz)}
                id={`student-quiz-item-${quiz._id}`}
              >
                <Card className="border border-base-300 bg-base-100 shadow-lg hover:shadow-xl hover:border-primary/20 transition-all duration-300 rounded-3xl overflow-hidden h-full flex flex-col justify-between">
                  <CardContent className="p-6 space-y-4 flex-1 flex flex-col justify-between">
                    <div>
                      <div className="flex items-center justify-between mb-3 gap-2">
                        <span className="badge badge-outline border-primary/40 text-primary text-[10px] font-bold px-2 py-2 rounded-lg truncate max-w-[150px]">
                          {quiz.courseId?.title || "Assigned Course"}
                        </span>
                        <span className="badge badge-neutral text-[10px] font-bold px-2.5 py-2.5 rounded-xl capitalize">
                          {quiz.quizType}
                        </span>
                      </div>

                      <h3 className="text-xl font-bold text-foreground line-clamp-1 mb-2">{quiz.title}</h3>
                      <p className="text-muted-foreground text-xs line-clamp-2 leading-relaxed mb-4">
                        {quiz.description || "Take this course assessment to evaluate your concepts."}
                      </p>
                    </div>

                    <div className="border-t border-base-300 pt-4 flex items-center justify-between text-xs font-semibold text-muted-foreground">
                      <div className="flex items-center gap-4">
                        <span className="flex items-center gap-1">
                          <Clock className="h-4 w-4 text-warning/80" /> {quiz.duration} mins
                        </span>
                        <span className="flex items-center gap-1">
                          <Award className="h-4 w-4 text-primary/80" /> {quiz.totalMarks} Marks
                        </span>
                      </div>

                      <Button
                        variant="ghost"
                        size="sm"
                        className="rounded-xl bg-base-200 hover:bg-primary hover:text-white p-2 flex items-center gap-1 text-[10px]"
                      >
                        Details <ChevronRight className="h-3.5 w-3.5" />
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            ))}
          </div>
        )}
      </motion.div>

      {/* QUIZ INSTRUCTIONS MODAL */}
      <Modal
        isOpen={!!selectedQuiz}
        onClose={() => setSelectedQuiz(null)}
        title={selectedQuiz?.title || "Assessment Guidelines"}
      >
        {selectedQuiz && (
          <div className="space-y-6">
            <div className="bg-gradient-to-r from-primary/10 to-base-200 p-5 rounded-2xl border border-primary/15 space-y-1.5">
              <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-wide">Target Course</span>
              <h3 className="font-bold text-lg text-foreground">{selectedQuiz.courseId?.title}</h3>
            </div>

            {selectedQuiz.instructions && (
              <div className="space-y-1.5">
                <span className="text-xs font-bold text-muted-foreground block">Quiz Instructions:</span>
                <p className="text-xs text-muted-foreground leading-relaxed bg-base-200 p-4 rounded-xl border border-base-300 font-mono overflow-auto max-h-[120px]">
                  {selectedQuiz.instructions}
                </p>
              </div>
            )}

            <div className="grid grid-cols-3 gap-3">
              <div className="p-3 bg-base-200 border border-base-300 rounded-xl text-center space-y-0.5">
                <span className="text-xl font-extrabold text-foreground">{selectedQuiz.duration}</span>
                <span className="text-[10px] font-bold text-muted-foreground block">Minutes</span>
              </div>
              <div className="p-3 bg-base-200 border border-base-300 rounded-xl text-center space-y-0.5">
                <span className="text-xl font-extrabold text-foreground">{selectedQuiz.totalMarks}</span>
                <span className="text-[10px] font-bold text-muted-foreground block">Total Marks</span>
              </div>
              <div className="p-3 bg-base-200 border border-base-300 rounded-xl text-center space-y-0.5">
                <span className="text-xl font-extrabold text-foreground">{selectedQuiz.passingMarks}</span>
                <span className="text-[10px] font-bold text-muted-foreground block">Pass score</span>
              </div>
            </div>

            {/* Attempts History List */}
            <div className="space-y-2">
              <span className="text-xs font-bold text-muted-foreground block">Your Attempts History:</span>
              {loadingAttempts ? (
                <div className="flex justify-center py-4">
                  <span className="loading loading-spinner loading-sm text-primary"></span>
                </div>
              ) : attemptsHistory.length === 0 ? (
                <p className="text-[10px] text-muted-foreground italic text-center py-3 bg-base-200 rounded-xl">
                  You haven't attempted this quiz yet.
                </p>
              ) : (
                <div className="space-y-1.5 max-h-[140px] overflow-y-auto">
                  {attemptsHistory.map((attempt, index) => (
                    <div
                      key={attempt._id}
                      onClick={() => {
                        setSelectedQuiz(null);
                        navigate(`/student/quizzes/result/${attempt._id}`);
                      }}
                      className="flex items-center justify-between bg-primary/5 hover:bg-primary/10 border border-primary/20 p-2.5 rounded-xl text-xs cursor-pointer transition-all"
                    >
                      <div className="flex items-center gap-2">
                        <CheckCircle2 className="h-4 w-4 text-success" />
                        <span className="font-bold text-foreground">Attempt #{attemptsHistory.length - index}</span>
                        <span className="text-[10px] text-muted-foreground">({new Date(attempt.submittedAt).toLocaleDateString()})</span>
                      </div>
                      <div className="flex items-center gap-3">
                        <span className="font-mono font-bold text-success">{attempt.score} / {selectedQuiz.totalMarks}</span>
                        <ChevronRight className="h-4 w-4 text-muted-foreground" />
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Action Start Button */}
            <Button
              onClick={handleStartAttempt}
              disabled={selectedQuiz.attemptLimit > 0 && attemptsHistory.length >= selectedQuiz.attemptLimit}
              className="btn btn-primary w-full rounded-2xl text-white font-bold h-12 flex items-center justify-center gap-2"
              id="student-start-quiz-btn"
            >
              <Sparkles className="h-5 w-5" />
              {selectedQuiz.attemptLimit > 0 && attemptsHistory.length >= selectedQuiz.attemptLimit
                ? "Attempt Limit Exceeded"
                : attemptsHistory.length > 0
                ? `Retake Quiz (${selectedQuiz.attemptLimit - attemptsHistory.length} Left)`
                : "Start Quiz Attempt"}
            </Button>
          </div>
        )}
      </Modal>
    </motion.div>
  );
}

