import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Bell, Megaphone, Clock, Send, ShieldAlert, RefreshCw } from "lucide-react";
import { Card, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Tabs, TabsList, TabsTrigger } from "../../../components/ui/Tabs";
import { getNotifications, sendNotification } from "../../../services/adminModulesService";
import NotificationCenter from "./NotificationCenter";
import CreateNotification from "./CreateNotification";
import NotificationHistory from "./NotificationHistory";

const container = {
  hidden: { opacity: 0 },
  show: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05,
    },
  },
};

const item = {
  hidden: { opacity: 0, y: 15 },
  show: { opacity: 1, y: 0 },
};

export default function AdminNotifications() {
  const [activeTab, setActiveTab] = useState("alerts");
  const [notifications, setNotifications] = useState([]);
  const [broadcasts, setBroadcasts] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchNotifications = async () => {
    try {
      setLoading(true);
      const res = await getNotifications();
      if (res && res.success) {
        // Divide notifications
        const allNotifs = res.data || [];
        setNotifications(allNotifs);

        // System broadcasts are filtered where type is 'announcement' or targetRole is defined
        const broads = allNotifs.filter((n) => n.targetRole === "all" || n.targetRole === "teacher" || n.targetRole === "student" || n.type === "announcement");
        setBroadcasts(broads);
      }
    } catch (err) {
      console.error("Error loading system notifications:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchNotifications();
  }, []);

  const handleMarkAsRead = (id) => {
    setNotifications((prev) =>
      prev.map((n) => (n._id === id ? { ...n, read: true } : n))
    );
  };

  const handleMarkAllRead = () => {
    setNotifications((prev) => prev.map((n) => ({ ...n, read: true })));
  };

  const handleDeleteNotification = (id) => {
    setNotifications((prev) => prev.filter((n) => n._id !== id));
  };

  const handleSendBroadcast = async (formData) => {
    const payload = {
      title: formData.title,
      message: formData.message,
      targetRole: formData.target,
      type: formData.type,
    };
    const res = await sendNotification(payload);
    if (res && res.success) {
      // Refresh notifications lists
      await fetchNotifications();
    } else {
      throw new Error(res?.message || "Failed to dispatch broadcast");
    }
  };

  const renderActiveTab = () => {
    switch (activeTab) {
      case "broadcast":
        return <CreateNotification onSend={handleSendBroadcast} />;
      case "history":
        return <NotificationHistory broadcasts={broadcasts} />;
      default:
        return (
          <NotificationCenter
            notifications={notifications}
            onMarkAsRead={handleMarkAsRead}
            onDelete={handleDeleteNotification}
            onMarkAllRead={handleMarkAllRead}
          />
        );
    }
  };

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="show"
      className="space-y-6 max-w-7xl mx-auto p-4 sm:p-6 lg:p-8"
      id="admin-notifications-container"
    >
      {/* Header */}
      <motion.div variants={item} className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 border-b border-border pb-5">
        <div>
          <h1 className="text-3xl font-extrabold tracking-tight text-foreground bg-gradient-to-r from-blue-500 to-indigo-500 bg-clip-text text-transparent">
            System Notifications
          </h1>
          <p className="text-sm text-muted-foreground mt-1">
            Dispatch announcements, inspect platform-wide alert logs, and target learning roles.
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            className="gap-2 font-medium"
            disabled={loading}
            onClick={fetchNotifications}
          >
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} /> Refresh Alerts
          </Button>
        </div>
      </motion.div>

      {/* Tabs */}
      <motion.div variants={item}>
        <Tabs value={activeTab} onValueChange={setActiveTab}>
          <TabsList className="bg-muted p-1 rounded-xl">
            <TabsTrigger value="alerts" className="gap-2 text-xs font-semibold">
              <Bell className="h-4 w-4" /> Live Alerts ({notifications.filter(n => !n.read).length})
            </TabsTrigger>
            <TabsTrigger value="broadcast" className="gap-2 text-xs font-semibold">
              <Megaphone className="h-4 w-4" /> Send Broadcast
            </TabsTrigger>
            <TabsTrigger value="history" className="gap-2 text-xs font-semibold">
              <Clock className="h-4 w-4" /> Broadcast History
            </TabsTrigger>
          </TabsList>
        </Tabs>
      </motion.div>

      {/* Main Tab Content */}
      <motion.div variants={item} className="mt-6">
        <AnimatePresence mode="wait">
          <motion.div
            key={activeTab}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            transition={{ duration: 0.15 }}
          >
            {renderActiveTab()}
          </motion.div>
        </AnimatePresence>
      </motion.div>
    </motion.div>
  );
}

import React, { useState } from "react";
import { Send, AlertCircle } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

export default function CreateNotification({
  onSend,
}) {
  const [target, setTarget] = useState("all");
  const [type, setType] = useState("info");
  const [title, setTitle] = useState("");
  const [message, setMessage] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!title.trim() || !message.trim()) {
      setError("Please fill in both the notification title and message body.");
      return;
    }

    try {
      setSubmitting(true);
      setError("");
      setSuccess("");
      await onSend({ target, type, title, message });
      setSuccess("Your broadcast has been successfully dispatched across the platform!");
      setTitle("");
      setMessage("");
    } catch (err) {
      setError(err?.message || "Failed to dispatch notification broadcast.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Card className="max-w-2xl mx-auto hover:shadow-md transition-all border border-border" id="create-notification-root">
      <CardHeader>
        <CardTitle className="text-lg text-foreground font-bold">Dispatch Targeted System Broadcast</CardTitle>
      </CardHeader>
      <CardContent>
        <form onSubmit={handleSubmit} className="space-y-5">
          {error && (
            <div className="p-3 bg-red-500/10 border border-red-500/20 text-red-500 text-xs rounded-lg flex items-center gap-2 font-medium">
              <AlertCircle className="h-4 w-4 shrink-0" /> {error}
            </div>
          )}

          {success && (
            <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 text-emerald-500 text-xs rounded-lg flex items-center gap-2 font-medium">
              <AlertCircle className="h-4 w-4 shrink-0" /> {success}
            </div>
          )}

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">Recipient Audience</label>
              <select
                className="w-full h-10 px-3 rounded-lg border border-border bg-card text-foreground text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                value={target}
                onChange={(e) => setTarget(e.target.value)}
              >
                <option value="all">All Platform Users</option>
                <option value="teachers">Verified Teachers Only</option>
                <option value="students">Registered Students Only</option>
              </select>
            </div>

            <div>
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">Alert Level Type</label>
              <select
                className="w-full h-10 px-3 rounded-lg border border-border bg-card text-foreground text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
                value={type}
                onChange={(e) => setType(e.target.value)}
              >
                <option value="info">Information (Blue Alert)</option>
                <option value="success">Success / Release (Green Alert)</option>
                <option value="warning">Warning / Notice (Amber Alert)</option>
                <option value="critical">Critical / Outage (Red Alert)</option>
              </select>
            </div>
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">Notification Title</label>
            <Input
              placeholder="e.g. Summer Break Extended Announcement"
              value={title}
              onChange={(e) => setTitle(e.target.value)}
            />
          </div>

          <div>
            <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block mb-1.5">Broadcast Message Content</label>
            <textarea
              className="w-full h-32 px-3 py-2 rounded-lg border border-border bg-card text-foreground text-sm focus:outline-none focus:ring-1 focus:ring-blue-500"
              placeholder="Type your official platform announcement message here..."
              value={message}
              onChange={(e) => setMessage(e.target.value)}
            />
          </div>

          <div className="pt-2 flex justify-end">
            <Button
              type="submit"
