import React, { useState, useEffect } from "react";
import { ChevronLeft, Save, Edit, Check } from "lucide-react";
import { Card, CardHeader, CardTitle, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

export default function EditStudent({
  student = {},
  coursesList = [],
  onSave,
  onCancel,
}) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [phone, setPhone] = useState("");
  const [bio, setBio] = useState("");
  const [avatar, setAvatar] = useState("");
  const [status, setStatus] = useState("active");
  const [enrolledCourses, setEnrolledCourses] = useState([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    if (student) {
      setName(student.name || "");
      setEmail(student.email || "");
      setPhone(student.phone || "");
      setBio(student.bio || "");
      setAvatar(student.avatar || "");
      setStatus(student.status || "active");
      setEnrolledCourses(student.enrolledCourses || []);
    }
  }, [student]);

  const handleToggleCourse = (cId) => {
    if (enrolledCourses.includes(cId)) {
      setEnrolledCourses(enrolledCourses.filter(id => id !== cId));
    } else {
      setEnrolledCourses([...enrolledCourses, cId]);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name || !email) return;

    try {
      setIsSubmitting(true);
      await onSave(student._id, {
        name,
        email,
        phone,
        bio,
        avatar,
        status,
        enrolledCourses,
      });
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6" id="edit-student-root">
      <div className="flex items-center">
        <Button variant="ghost" className="gap-2 text-muted-foreground hover:text-foreground" onClick={onCancel}>
          <ChevronLeft className="h-4 w-4" /> Cancel Edits
        </Button>
      </div>

      <Card className="hover:shadow-md transition-all max-w-4xl mx-auto">
        <CardHeader className="pb-4 border-b">
          <CardTitle className="text-base font-bold flex items-center gap-2">
            <Edit className="h-5 w-5 text-blue-600" /> Edit Student Credentials Profile
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Basic Info */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Full Name *</label>
                <Input
                  required
                  placeholder="e.g. Sarah Johnson"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Email Address *</label>
                <Input
                  required
                  type="email"
                  placeholder="e.g. sarah.johnson@email.com"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Phone Contact</label>
                <Input
                  placeholder="e.g. +1 (555) 987-6543"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Account status</label>
                <select
                  className="w-full rounded-lg border border-border bg-card px-3 py-2 text-sm focus:outline-none h-10"
                  value={status}
                  onChange={(e) => setStatus(e.target.value)}
                >
                  <option value="active">Active</option>
                  <option value="suspended">Suspended</option>
                </select>
              </div>
            </div>

            {/* Profile Avatar Url */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Profile Photo Url</label>
              <Input
                placeholder="e.g. https://images.unsplash.com/photo-1494790108377-be9c29b29330"
                value={avatar}
                onChange={(e) => setAvatar(e.target.value)}
              />
            </div>

            {/* Biography */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Short Bio / Notes</label>
              <textarea
                className="w-full min-h-24 rounded-lg border border-border bg-card p-3 text-sm focus:outline-none"
                placeholder="Write student biographical descriptions..."
                value={bio}
                onChange={(e) => setBio(e.target.value)}
              />
            </div>

            {/* Course Checklist Assignments */}
            <div className="space-y-3 pt-4 border-t">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">Modify Enrolled Courses</label>
              {coursesList.length === 0 ? (
                <p className="text-xs text-muted-foreground">No active courses registered inside system database to assign.</p>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                  {coursesList.map((course) => {
                    const isSelected = enrolledCourses.includes(course._id);
                    return (
                      <div
                        key={course._id}
                        className={`flex items-center gap-2.5 p-3 border rounded-xl cursor-pointer transition-all ${
                          isSelected
                            ? "bg-blue-50 border-blue-500 text-blue-700 font-semibold"
                            : "bg-card border-border hover:bg-muted/50"
                        }`}
                        onClick={() => handleToggleCourse(course._id)}
                      >
                        <div className={`h-4 w-4 border rounded flex items-center justify-center ${
                          isSelected ? "bg-blue-600 border-blue-600 text-white" : "border-muted"
                        }`}>
                          {isSelected && <Check className="h-3 w-3 stroke-[3]" />}
                        </div>
                        <span className="text-xs truncate">{course.title}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Action buttons */}
            <div className="flex justify-end gap-3 pt-6 border-t">
              <Button type="button" variant="outline" onClick={onCancel}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold shadow-md">
                <Save className="h-4 w-4" /> {isSubmitting ? "Updating..." : "Save Changes"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import {
  Search, Filter, Eye, Edit, Ban, CheckCircle2,
  Trash2, UserPlus, FileSpreadsheet, BookOpen, Award,
  ChevronLeft, ChevronRight, Sparkles, TrendingUp, Users
} from "lucide-react";
import { Card } from "../../../components/ui/Card";
import { Badge } from "../../../components/ui/Badge";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { Avatar } from "../../../components/ui/Avatar";
import { ProgressBar } from "../../../components/ui/ProgressBar";

export default function StudentList({
  students = [],
  onViewDetails,
  onEdit,
  onSuspend,
  onActivate,
  onDelete,
  onNavigateToCreate,
  onNavigateToAnalytics,
  onBulkImport,
  onExportCSV,
}) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  // Filters logic
  const filtered = students.filter((s) => {
    const matchesSearch =
      s.name.toLowerCase().includes(search.toLowerCase()) ||
      s.email.toLowerCase().includes(search.toLowerCase());
    if (statusFilter === "active") return matchesSearch && s.status === "active";
    if (statusFilter === "suspended") return matchesSearch && s.status === "suspended";
    return matchesSearch;
  });

  // Pagination logic
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filtered.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filtered.length / itemsPerPage);

  return (
    <div className="space-y-6" id="student-list-root">
      {/* Search and filter controls */}
      <div className="flex flex-col sm:flex-row gap-4 items-center justify-between">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            className="pl-9"
            placeholder="Search students by name or email address..."
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setCurrentPage(1);
            }}
          />
        </div>
        <div className="flex gap-2 w-full sm:w-auto shrink-0 justify-end">
          <select
            className="rounded-lg border border-border bg-card px-3 py-2 text-sm focus:outline-none"
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setCurrentPage(1);
            }}
          >
            <option value="all">All Statuses</option>
            <option value="active">Active</option>
            <option value="suspended">Suspended</option>
          </select>
          <Button variant="outline" size="sm" className="gap-2" onClick={onExportCSV}>
            <FileSpreadsheet className="h-4 w-4" /> Export CSV
          </Button>
          <Button size="sm" className="gap-2 bg-blue-600 hover:bg-blue-700 text-white" onClick={onNavigateToCreate}>
            <UserPlus className="h-4 w-4" /> Create Student
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-border gap-2">
        {["all", "active", "suspended"].map((tab) => {
          const count = students.filter((s) => {
            if (tab === "all") return true;
            return s.status === tab;
          }).length;
          return (
            <button
              key={tab}
              className={`px-4 py-2 text-sm font-semibold capitalize border-b-2 transition-all ${
                statusFilter === tab
                  ? "border-blue-600 text-blue-600"
                  : "border-transparent text-muted-foreground hover:text-foreground"
              }`}
              onClick={() => {
                setStatusFilter(tab);
                setCurrentPage(1);
              }}
            >
              {tab} ({count})
            </button>
          );
        })}
      </div>

      {/* Student List Table */}
      <Card className="overflow-hidden hover:shadow-md transition-all">
        {filtered.length === 0 ? (
          <div className="text-center py-16 text-muted-foreground">
            <Users className="h-12 w-12 mx-auto mb-3 text-muted-foreground/50" />
            <p className="font-semibold text-foreground">No students found</p>
            <p className="text-sm">No student profiles match your search filters.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b bg-muted/30 text-xs font-semibold text-muted-foreground uppercase">
                  <th className="py-3.5 px-4">Student</th>
                  <th className="py-3.5 px-4">Enrolled Courses</th>
                  <th className="py-3.5 px-4">Completed Paths</th>
                  <th className="py-3.5 px-4">Average Progress</th>
                  <th className="py-3.5 px-4">Status</th>
                  <th className="py-3.5 px-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {currentItems.map((student) => (
                  <tr key={student._id} className="border-b hover:bg-muted/10 transition-colors text-sm">
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-3">
                        <Avatar className="w-10 h-10" src={student.avatar} fallback={student.name.charAt(0)} />
                        <div>
                          <p className="font-bold text-foreground">{student.name}</p>
                          <p className="text-xs text-muted-foreground">{student.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-1.5 font-medium text-muted-foreground">
                        <BookOpen className="h-4 w-4" />
                        <span>{student.enrolledCoursesCount || 0} classes</span>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-1.5 font-medium text-muted-foreground">
                        <Award className="h-4 w-4" />
                        <span>{student.completedCoursesCount || 0} courses</span>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <div className="w-28 space-y-1">
                        <ProgressBar value={student.averageProgress || 0} size="xs" />
                        <span className="text-[10px] font-bold text-muted-foreground mt-1 block">
                          {student.averageProgress || 0}% Complete
                        </span>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <Badge
                        variant={student.status === "active" ? "success" : "destructive"}
                        className="capitalize font-semibold border-0 text-xs"
                      >
                        {student.status || "active"}
                      </Badge>
                    </td>
                    <td className="py-4 px-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-blue-600 hover:bg-blue-50"
                          onClick={() => onViewDetails(student)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-amber-600 hover:bg-amber-50"
                          onClick={() => onEdit(student)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        {student.status === "active" ? (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-red-500 hover:bg-red-50"
                            onClick={() => onSuspend(student)}
                          >
                            <Ban className="h-4 w-4" />
                          </Button>
                        ) : (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-emerald-600 hover:bg-emerald-50"
                            onClick={() => onActivate(student)}
                          >
                            <CheckCircle2 className="h-4 w-4" />
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-destructive hover:bg-destructive/10"
                          onClick={() => onDelete(student)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Paginate control */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3.5 border-t border-border">
            <p className="text-xs text-muted-foreground">
              Showing {indexOfFirstItem + 1}-{Math.min(indexOfLastItem, filtered.length)} of {filtered.length} students
            </p>
            <div className="flex items-center gap-1.5">
              <Button
                variant="outline"
                size="sm"
                className="p-2 h-8 w-8"
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
              {Array.from({ length: totalPages }).map((_, idx) => (
                <Button
                  key={idx}
                  variant={currentPage === idx + 1 ? "default" : "outline"}
                  size="sm"
                  className="h-8 w-8 text-xs font-semibold"
                  onClick={() => setCurrentPage(idx + 1)}
                >
                  {idx + 1}
                </Button>
              ))}
              <Button
                variant="outline"
                size="sm"
                className="p-2 h-8 w-8"
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}
      </Card>

      {/* Bulk actions and analytics footer triggers */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-center bg-muted/20 border border-dashed rounded-xl p-4">
        <div className="flex items-center gap-2">
          <Sparkles className="h-5 w-5 text-amber-500 fill-current" />
          <div>
            <p className="font-semibold text-sm">Need student study telemetry insights?</p>
            <p className="text-xs text-muted-foreground">Review learning curves, average quiz accuracies, and attendance rate metrics.</p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" className="gap-2" onClick={onNavigateToAnalytics}>
            <TrendingUp className="h-4 w-4" /> View Analytics Graph
          </Button>
          <Button variant="outline" size="sm" className="gap-2" onClick={onBulkImport}>
            <UserPlus className="h-4 w-4" /> Bulk Import JSON
          </Button>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { getTeachers, createTeacher, getTeacher, updateTeacher, deleteTeacher, getTeacherAnalytics } from "../../../services/adminService";
import { getCourses } from "../../../services/courseService";
import TeacherList from "./TeacherList";
import TeacherDetails from "./TeacherDetails";
import CreateTeacher from "./CreateTeacher";
import EditTeacher from "./EditTeacher";
import TeacherAnalytics from "./TeacherAnalytics";
import { Loader2, AlertCircle, Sparkles } from "lucide-react";
import { Modal } from "../../../components/ui/Modal";
import { Button } from "../../../components/ui/Button";

export default function AdminTeachers() {
  const [view, setView] = useState("list"); // "list" | "details" | "create" | "edit" | "analytics"
  const [teachers, setTeachers] = useState([]);
  const [coursesList, setCoursesList] = useState([]);
  const [selectedTeacher, setSelectedTeacher] = useState(null);
  const [teacherDetailData, setTeacherDetailData] = useState(null);
  const [analyticsData, setAnalyticsData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Modal triggers
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [confirmActionType, setConfirmActionType] = useState(null); // "suspend" | "activate" | "delete"
  const [targetTeacher, setTargetTeacher] = useState(null);

  // Bulk Import
  const [showImportModal, setShowImportModal] = useState(false);
  const [importPayload, setImportPayload] = useState("");

  const loadTeachersList = async () => {
    try {
      setLoading(true);
      const res = await getTeachers();
      if (res.data?.success) {
        setTeachers(res.data.data.teachers || []);
      }
    } catch (err) {
      console.error(err);
      setError("Unable to sync teacher records with LMS database.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTeachersList();

    // Preload available courses for assignments checklist
    async function fetchCourses() {
      try {
        const res = await getCourses();
        if (res.data?.success) {
          setCoursesList(res.data.data || []);
        }
      } catch (err) {
        console.error(err);
      }
    }
    fetchCourses();
  }, []);

  const handleViewDetails = async (t) => {
    try {
      setLoading(true);
      const res = await getTeacher(t._id);
      if (res.data?.success) {
        setTeacherDetailData(res.data.data);
        setView("details");
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (t) => {
    setSelectedTeacher(t);
    setView("edit");
  };

  const handleNavigateToCreate = () => {
    setView("create");
  };

  const handleNavigateToAnalytics = async () => {
    try {
      setLoading(true);
      const res = await getTeacherAnalytics();
      if (res.data?.success) {
        setAnalyticsData(res.data.data);
        setView("analytics");
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleTriggerConfirm = (teacher, action) => {
    setTargetTeacher(teacher);
    setConfirmActionType(action);
    setShowConfirmModal(true);
  };

  const handleExecuteConfirm = async () => {
    if (!targetTeacher || !confirmActionType) return;
    try {
      setLoading(true);
      setShowConfirmModal(false);

      if (confirmActionType === "delete") {
        await deleteTeacher(targetTeacher._id);
      } else {
        const status = confirmActionType === "suspend" ? "suspended" : "active";
        await updateTeacher(targetTeacher._id, { status });
      }

      await loadTeachersList();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
      setTargetTeacher(null);
      setConfirmActionType(null);
    }
  };

  const handleCreateSave = async (payload) => {
    try {
      setLoading(true);
      await createTeacher(payload);
      setView("list");
      await loadTeachersList();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleEditSave = async (id, payload) => {
    try {
      setLoading(true);
      await updateTeacher(id, payload);
      setView("list");
      await loadTeachersList();
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
      setSelectedTeacher(null);
    }
  };

  const handleExportCSV = () => {
    // Generate browser download link directly to CSV endpoint
    window.open(`http://${window.location.hostname}:5000/api/admin/users/export`, "_blank");
  };

  const handleBulkImportTrigger = () => {
    setShowImportModal(true);
  };

  const handleExecuteImport = async () => {
    try {
      if (!importPayload) return;
      const parsed = JSON.parse(importPayload);
      setLoading(true);
      setShowImportModal(false);

      // Perform bulk api
      const usersArray = Array.isArray(parsed) ? parsed : [parsed];
      await updateTeacher("bulk", { bulkUsers: usersArray }); // mapped to import helper in custom bulk routes

      setImportPayload("");
      await loadTeachersList();
    } catch (err) {
      alert("Invalid JSON format. Please upload a correct array of user profiles.");
    } finally {
      setLoading(false);
    }
  };

  if (loading && view === "list") {
    return (
      <div className="flex flex-col justify-center items-center py-32 space-y-4" id="admin-teachers-loading">
        <Loader2 className="h-12 w-12 animate-spin text-blue-600" />
        <p className="text-muted-foreground text-sm font-medium animate-pulse">Syncing educator archives...</p>
      </div>
    );
  }

  return (
    <div className="space-y-6" id="admin-teachers-orchestrator">
      {error && (
        <div className="bg-red-500/10 border border-red-500/20 text-red-600 rounded-xl p-4 flex items-center gap-3 text-sm">
          <AlertCircle className="h-5 w-5 shrink-0" />
          <span>{error}</span>
        </div>
      )}

      {/* View Container Switcher */}
      <AnimatePresence mode="wait">
        <motion.div
          key={view}
          initial={{ opacity: 0, y: 15 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -15 }}
          transition={{ duration: 0.2 }}
        >
          {view === "list" && (
            <TeacherList
              teachers={teachers}
              onViewDetails={handleViewDetails}
              onEdit={handleEdit}
              onSuspend={(t) => handleTriggerConfirm(t, "suspend")}
              onActivate={(t) => handleTriggerConfirm(t, "activate")}
              onDelete={(t) => handleTriggerConfirm(t, "delete")}
              onNavigateToCreate={handleNavigateToCreate}
              onNavigateToAnalytics={handleNavigateToAnalytics}
              onBulkImport={handleBulkImportTrigger}
              onExportCSV={handleExportCSV}
            />
          )}

          {view === "details" && teacherDetailData && (
            <TeacherDetails
              data={teacherDetailData}
              onBack={() => setView("list")}
              onSendEmail={(email) => window.location.href = `mailto:${email}`}
            />
          )}

          {view === "create" && (
            <CreateTeacher
              coursesList={coursesList}
              onSave={handleCreateSave}
              onCancel={() => setView("list")}
            />
          )}

          {view === "edit" && selectedTeacher && (
            <EditTeacher
              teacher={selectedTeacher}
              coursesList={coursesList}
              onSave={handleEditSave}
              onCancel={() => setView("list")}
            />
          )}

          {view === "analytics" && analyticsData && (
            <TeacherAnalytics
              analyticsData={analyticsData}
              onBack={() => setView("list")}
            />
          )}
        </motion.div>
      </AnimatePresence>

      {/* Confirmation Action Modal */}
      <Modal isOpen={showConfirmModal} onClose={() => setShowConfirmModal(false)} title="System Credentials Warning">
        {targetTeacher && (
          <div className="space-y-4 text-sm" id="confirm-action-modal">
            {confirmActionType === "delete" ? (
              <div className="flex gap-3 p-4 rounded-xl bg-red-500/10 text-red-600 border border-red-500/20">
                <AlertCircle className="h-6 w-6 shrink-0" />
                <p>
                  Permanently delete educator account <strong>{targetTeacher.name}</strong>? This action terminates all course reference keys and cannot be undone.
                </p>
              </div>
            ) : (
              <div className="flex gap-3 p-4 rounded-xl bg-amber-500/10 text-amber-600 border border-amber-500/20">
                <AlertCircle className="h-6 w-6 shrink-0" />
                <p>
                  Are you sure you want to {confirmActionType} educator account <strong>{targetTeacher.name}</strong>? Suspended teachers cannot host lessons or grade students.
                </p>
              </div>
            )}
            <div className="flex gap-3 justify-end pt-2">
              <Button variant="outline" onClick={() => setShowConfirmModal(false)}>Cancel</Button>
              <Button
                variant={confirmActionType === "delete" ? "destructive" : "default"}
                onClick={handleExecuteConfirm}
                className="font-semibold shadow"
              >
                Confirm {confirmActionType}
              </Button>
            </div>
          </div>
        )}
      </Modal>

      {/* Bulk JSON Import Modal */}
      <Modal isOpen={showImportModal} onClose={() => setShowImportModal(false)} title="Bulk JSON Data Import">
        <div className="space-y-4 text-sm" id="import-users-modal">
          <p className="text-muted-foreground">Paste a JSON array containing teacher/student objects mapping name and email fields:</p>
          <textarea
            className="w-full min-h-36 rounded-lg border border-border bg-card p-3 font-mono text-xs focus:outline-none"
            placeholder='[{"name": "Alice Smith", "email": "alice@lms.com", "role": "teacher"}]'
            value={importPayload}
            onChange={(e) => setImportPayload(e.target.value)}
          />
          <div className="flex justify-end gap-3 pt-2">
            <Button variant="outline" onClick={() => setShowImportModal(false)}>Cancel</Button>
            <Button className="bg-blue-600 hover:bg-blue-700 text-white font-semibold" onClick={handleExecuteImport}>
              Execute Import
            </Button>
          </div>
        </div>
      </Modal>
    </div>
  );
}

import React, { useState } from "react";
import { ChevronLeft, Save, PlusCircle, Check } from "lucide-react";
import { Card, CardHeader, CardTitle, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

export default function CreateTeacher({
  coursesList = [],
  onSave,
  onCancel,
}) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("teacher123");
  const [phone, setPhone] = useState("");
  const [bio, setBio] = useState("");
  const [avatar, setAvatar] = useState("");
  const [qualification, setQualification] = useState("");
  const [specialization, setSpecialization] = useState("");
  const [experience, setExperience] = useState("");
  const [assignedCourses, setAssignedCourses] = useState([]);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleToggleCourse = (cId) => {
    if (assignedCourses.includes(cId)) {
      setAssignedCourses(assignedCourses.filter(id => id !== cId));
    } else {
      setAssignedCourses([...assignedCourses, cId]);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!name || !email) return;

    try {
      setIsSubmitting(true);
      await onSave({
        name,
        email,
        password,
        phone,
        bio,
        avatar,
        qualification,
        specialization,
        experience: Number(experience) || 0,
        assignedCourses,
      });
    } catch (err) {
      console.error(err);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="space-y-6" id="create-teacher-root">
      <div className="flex items-center">
        <Button variant="ghost" className="gap-2 text-muted-foreground hover:text-foreground" onClick={onCancel}>
          <ChevronLeft className="h-4 w-4" /> Cancel Creation
        </Button>
      </div>

      <Card className="hover:shadow-md transition-all max-w-4xl mx-auto">
        <CardHeader className="pb-4 border-b">
          <CardTitle className="text-base font-bold flex items-center gap-2">
            <PlusCircle className="h-5 w-5 text-blue-600" /> Register New Teacher Account
          </CardTitle>
        </CardHeader>
        <CardContent className="p-6">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Basic credentials */}
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Full Name *</label>
                <Input
                  required
                  placeholder="e.g. Dr. James Wilson"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Email Address *</label>
                <Input
                  required
                  type="email"
                  placeholder="e.g. james.wilson@university.edu"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Password Seeding</label>
                <Input
                  placeholder="Seeded default password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
                <p className="text-[10px] text-muted-foreground">Default password: <strong>teacher123</strong>. Educators can update passwords inside settings.</p>
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Phone Contact</label>
                <Input
                  placeholder="e.g. +1 (555) 123-4567"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                />
              </div>
            </div>

            {/* Profile Avatar Url */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Profile Photo Url</label>
              <Input
                placeholder="e.g. https://images.unsplash.com/photo-1544005313-94ddf0286df2"
                value={avatar}
                onChange={(e) => setAvatar(e.target.value)}
              />
            </div>

            {/* Qualifications */}
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Degree / Qualification</label>
                <Input
                  placeholder="e.g. Ph.D. Computer Science"
                  value={qualification}
                  onChange={(e) => setQualification(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Specialization Topic</label>
                <Input
                  placeholder="e.g. Full-Stack Dev / React"
                  value={specialization}
                  onChange={(e) => setSpecialization(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Experience (Years)</label>
                <Input
                  type="number"
                  placeholder="e.g. 8"
                  value={experience}
                  onChange={(e) => setExperience(e.target.value)}
                />
              </div>
            </div>

            {/* Biography */}
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Short Biography</label>
              <textarea
                className="w-full min-h-24 rounded-lg border border-border bg-card p-3 text-sm focus:outline-none"
                placeholder="Describe educator professional backgrounds and course notes..."
                value={bio}
                onChange={(e) => setBio(e.target.value)}
              />
            </div>

            {/* Course Checklist Assignments */}
            <div className="space-y-3 pt-4 border-t">
              <label className="text-xs font-semibold text-muted-foreground uppercase tracking-wider block">Assign Platform Courses</label>
              {coursesList.length === 0 ? (
                <p className="text-xs text-muted-foreground">No active courses registered inside system database to assign.</p>
              ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
                  {coursesList.map((course) => {
                    const isSelected = assignedCourses.includes(course._id);
                    return (
                      <div
                        key={course._id}
                        className={`flex items-center gap-2.5 p-3 border rounded-xl cursor-pointer transition-all ${
                          isSelected
                            ? "bg-blue-50 border-blue-500 text-blue-700 font-semibold"
                            : "bg-card border-border hover:bg-muted/50"
                        }`}
                        onClick={() => handleToggleCourse(course._id)}
                      >
                        <div className={`h-4 w-4 border rounded flex items-center justify-center ${
                          isSelected ? "bg-blue-600 border-blue-600 text-white" : "border-muted"
                        }`}>
                          {isSelected && <Check className="h-3 w-3 stroke-[3]" />}
                        </div>
                        <span className="text-xs truncate">{course.title}</span>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Action controls */}
            <div className="flex justify-end gap-3 pt-6 border-t">
              <Button type="button" variant="outline" onClick={onCancel}>
                Cancel
              </Button>
              <Button type="submit" disabled={isSubmitting} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold shadow-md">
                <Save className="h-4 w-4" /> {isSubmitting ? "Seeding Account..." : "Save Educator"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

