              <Button type="submit" disabled={isSubmitting} className="gap-2 bg-blue-600 hover:bg-blue-700 text-white font-semibold shadow-md">
                <Save className="h-4 w-4" /> {isSubmitting ? "Updating..." : "Save Changes"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState } from "react";
import {
  Search, Filter, Eye, Edit, Ban, CheckCircle2,
  Trash2, UserPlus, FileSpreadsheet, Mail, BookOpen, Users,
  ChevronLeft, ChevronRight, AlertTriangle, Sparkles, TrendingUp
} from "lucide-react";
import { Card } from "../../../components/ui/Card";
import { Badge } from "../../../components/ui/Badge";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { Avatar } from "../../../components/ui/Avatar";

export default function TeacherList({
  teachers = [],
  loading = false,
  onViewDetails,
  onEdit,
  onSuspend,
  onActivate,
  onDelete,
  onNavigateToCreate,
  onNavigateToAnalytics,
  onBulkImport,
  onExportCSV,
}) {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 6;

  // Filter
  const filtered = teachers.filter((t) => {
    const matchesSearch =
      t.name.toLowerCase().includes(search.toLowerCase()) ||
      t.email.toLowerCase().includes(search.toLowerCase());
    if (statusFilter === "active") return matchesSearch && t.status === "active";
    if (statusFilter === "suspended") return matchesSearch && t.status === "suspended";
    if (statusFilter === "pending") return matchesSearch && t.status === "pending";
    return matchesSearch;
  });

  // Paginate
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filtered.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filtered.length / itemsPerPage);

  return (
    <div className="space-y-6" id="teacher-list-root">
      {/* Search and Filters */}
      <div className="flex flex-col sm:flex-row gap-4 items-center justify-between">
        <div className="relative flex-1 w-full">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            className="pl-9"
            placeholder="Search educators by name or email address..."
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setCurrentPage(1);
            }}
          />
        </div>
        <div className="flex gap-2 w-full sm:w-auto shrink-0 justify-end">
          <select
            className="rounded-lg border border-border bg-card px-3 py-2 text-sm focus:outline-none"
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setCurrentPage(1);
            }}
          >
            <option value="all">All Statuses</option>
            <option value="active">Active</option>
            <option value="suspended">Suspended</option>
            <option value="pending">Pending</option>
          </select>
          <Button variant="outline" size="sm" className="gap-2" onClick={onExportCSV}>
            <FileSpreadsheet className="h-4 w-4" /> Export CSV
          </Button>
          <Button size="sm" className="gap-2 bg-blue-600 hover:bg-blue-700 text-white" onClick={onNavigateToCreate}>
            <UserPlus className="h-4 w-4" /> Create Educator
          </Button>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-border gap-2">
        {["all", "active", "suspended", "pending"].map((tab) => {
          const count = teachers.filter((t) => {
            if (tab === "all") return true;
            return t.status === tab;
          }).length;
          return (
            <button
              key={tab}
              className={`px-4 py-2 text-sm font-semibold capitalize border-b-2 transition-all ${
                statusFilter === tab
                  ? "border-blue-600 text-blue-600"
                  : "border-transparent text-muted-foreground hover:text-foreground"
              }`}
              onClick={() => {
                setStatusFilter(tab);
                setCurrentPage(1);
              }}
            >
              {tab} ({count})
            </button>
          );
        })}
      </div>

      {/* Responsive Table */}
      <Card className="overflow-hidden hover:shadow-md transition-all">
        {filtered.length === 0 ? (
          <div className="text-center py-16 text-muted-foreground">
            <Users className="h-12 w-12 mx-auto mb-3 text-muted-foreground/50" />
            <p className="font-semibold text-foreground">No educators found</p>
            <p className="text-sm">No teacher records match your criteria.</p>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="border-b bg-muted/30 text-xs font-semibold text-muted-foreground uppercase">
                  <th className="py-3.5 px-4">Educator Details</th>
                  <th className="py-3.5 px-4">Courses</th>
                  <th className="py-3.5 px-4">Students Enrolled</th>
                  <th className="py-3.5 px-4">Credentials Status</th>
                  <th className="py-3.5 px-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {currentItems.map((teacher) => (
                  <tr key={teacher._id} className="border-b hover:bg-muted/10 transition-colors text-sm">
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-3">
                        <Avatar className="w-10 h-10" src={teacher.avatar} fallback={teacher.name.charAt(0)} />
                        <div>
                          <p className="font-bold text-foreground">{teacher.name}</p>
                          <p className="text-xs text-muted-foreground">{teacher.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-1.5 font-medium text-muted-foreground">
                        <BookOpen className="h-4 w-4" />
                        <span>{teacher.coursesCount || 0} classes</span>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <div className="flex items-center gap-1.5 font-medium text-muted-foreground">
                        <Users className="h-4 w-4" />
                        <span>{(teacher.studentsCount || 0).toLocaleString()}</span>
                      </div>
                    </td>
                    <td className="py-4 px-4">
                      <Badge
                        variant={
                          teacher.status === "active"
                            ? "success"
                            : teacher.status === "suspended"
                            ? "destructive"
                            : "warning"
                        }
                        className="capitalize font-semibold border-0 text-xs"
                      >
                        {teacher.status || "active"}
                      </Badge>
                    </td>
                    <td className="py-4 px-4 text-right">
                      <div className="flex items-center justify-end gap-1.5">
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-blue-600 hover:bg-blue-50"
                          onClick={() => onViewDetails(teacher)}
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-amber-600 hover:bg-amber-50"
                          onClick={() => onEdit(teacher)}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        {teacher.status === "active" ? (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-red-500 hover:bg-red-50"
                            onClick={() => onSuspend(teacher)}
                          >
                            <Ban className="h-4 w-4" />
                          </Button>
                        ) : (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-8 w-8 text-emerald-600 hover:bg-emerald-50"
                            onClick={() => onActivate(teacher)}
                          >
                            <CheckCircle2 className="h-4 w-4" />
                          </Button>
                        )}
                        <Button
                          variant="ghost"
                          size="icon"
                          className="h-8 w-8 text-destructive hover:bg-destructive/10"
                          onClick={() => onDelete(teacher)}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* Paginate control */}
        {totalPages > 1 && (
          <div className="flex items-center justify-between px-4 py-3.5 border-t border-border">
            <p className="text-xs text-muted-foreground">
              Showing {indexOfFirstItem + 1}-{Math.min(indexOfLastItem, filtered.length)} of {filtered.length} teachers
            </p>
            <div className="flex items-center gap-1.5">
              <Button
                variant="outline"
                size="sm"
                className="p-2 h-8 w-8"
                onClick={() => setCurrentPage(prev => Math.max(prev - 1, 1))}
                disabled={currentPage === 1}
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>
              {Array.from({ length: totalPages }).map((_, idx) => (
                <Button
                  key={idx}
                  variant={currentPage === idx + 1 ? "default" : "outline"}
                  size="sm"
                  className="h-8 w-8 text-xs font-semibold"
                  onClick={() => setCurrentPage(idx + 1)}
                >
                  {idx + 1}
                </Button>
              ))}
              <Button
                variant="outline"
                size="sm"
                className="p-2 h-8 w-8"
                onClick={() => setCurrentPage(prev => Math.min(prev + 1, totalPages))}
                disabled={currentPage === totalPages}
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>
          </div>
        )}
      </Card>

      {/* Bulk actions and analytics footer triggers */}
      <div className="flex flex-col sm:flex-row gap-4 justify-between items-center bg-muted/20 border border-dashed rounded-xl p-4">
        <div className="flex items-center gap-2">
          <Sparkles className="h-5 w-5 text-amber-500 fill-current" />
          <div>
            <p className="font-semibold text-sm">Need deep system insights?</p>
            <p className="text-xs text-muted-foreground">View global attendance growth indexes and course enrollments.</p>
          </div>
        </div>
        <div className="flex gap-2">
          <Button variant="outline" size="sm" className="gap-2" onClick={onNavigateToAnalytics}>
            <TrendingUp className="h-4 w-4" /> View Analytics Graph
          </Button>
          <Button variant="outline" size="sm" className="gap-2" onClick={onBulkImport}>
            <UserPlus className="h-4 w-4" /> Bulk Import JSON
          </Button>
        </div>
      </div>
    </div>
  );
}

// src/pages/teacher/assignments/TeacherAssignmentManagement.jsx

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import {
  Plus,
  Search,
  ClipboardList,
  CheckCircle,
  FileText,
  Edit3,
  Trash2,
  Calendar,
  FileCheck,
  Sparkles,
  ChevronRight,
  BrainCircuit,
  Eye,
  AlertTriangle,
} from "lucide-react";
import { Card, CardHeader, CardTitle, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";
import { getCourses } from "../../../services/courseService";
import {
  getAssignments,
  createAssignment,
  deleteAssignment,
  generateAssignmentDraft,
} from "../../../services/assignmentService";
import toast from "react-hot-toast";

export default function TeacherAssignmentManagement() {
  const navigate = useNavigate();

  // Data States
  const [assignments, setAssignments] = useState([]);
  const [courses, setCourses] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");

  // Modals & Panels Active state
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [activeFormTab, setActiveFormTab] = useState("manual"); // "manual" or "ai"

  // Manual Form States
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [instructions, setInstructions] = useState("");
  const [courseId, setCourseId] = useState("");
  const [dueDate, setDueDate] = useState("");
  const [totalMarks, setTotalMarks] = useState(100);
  const [assignmentType, setAssignmentType] = useState("written");

  // AI Generator States
  const [notesText, setNotesText] = useState("");
  const [topicTitle, setTopicTitle] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);

  // Load Assignments & Courses
  useEffect(() => {
    async function loadData() {
      try {
        setLoading(true);
        const [assRes, coursesRes] = await Promise.all([
          getAssignments(),
          getCourses()
        ]);

        if (assRes.data?.success) {
          setAssignments(assRes.data.data || []);
        }
        if (coursesRes.data?.success) {
          const coursesList = coursesRes.data.data || [];
          setCourses(coursesList);
          if (coursesList.length > 0) {
            setCourseId(coursesList[0]._id);
          }
        }
      } catch (err) {
        console.error("Error loading teacher assignments workspace:", err);
        toast.error("Failed to load assignments and courses");
      } finally {
        setLoading(false);
      }
    }
    loadData();
  }, []);

  // AI Generation Trigger
  const handleAIGenerate = async (e) => {
    e.preventDefault();
    if (!topicTitle.trim() && !notesText.trim()) {
      toast.error("Please provide either a Topic Title or paste Lecture Notes/Keywords.");
      return;
    }

    try {
      setIsGenerating(true);
      const res = await generateAssignmentDraft({ notesText, topicTitle });

      if (res.data?.success) {
        const draft = res.data.data;
        // Populate standard form states automatically
        setTitle(draft.title || "");
        setDescription(draft.description || "");
        setInstructions(draft.instructions || "");
        setAssignmentType("mcq"); // Set a draft type
        setActiveFormTab("manual"); // Shift view to standard form so instructor can review
        toast.success("AI draft brief compiled! Review and save below.");
      } else {
        toast.error("Failed to generate questions");
      }
    } catch (err) {
      console.error("Error generating draft:", err);
      toast.error("AI question parsing failed");
    } finally {
      setIsGenerating(false);
    }
  };

  // Submit manual assignment
  const handlePublishAssignment = async (e) => {
    e.preventDefault();
    if (!title.trim() || !courseId || !dueDate) {
      toast.error("Title, Target Course, and Due Date are required fields.");
      return;
    }

    try {
      const res = await createAssignment({
        title,
        description,
        instructions,
        courseId,
        dueDate,
        totalMarks: Number(totalMarks),
        assignmentType,
        generatedFromDocument: activeFormTab === "ai" || instructions.includes("MCQ"),
      });

      if (res.data?.success) {
        setAssignments([res.data.data, ...assignments]);
        // Reset states
        setTitle("");
        setDescription("");
        setInstructions("");
        setDueDate("");
        setNotesText("");
        setTopicTitle("");
        setShowCreateModal(false);
        toast.success("Assignment published successfully to course enrolled students!");
      } else {
        toast.error("Failed to create assignment");
      }
    } catch (err) {
      console.error("Error creating assignment:", err);
      toast.error("Encountered error publishing assignment sheet");
    }
  };

  // Delete Assignment Handler
  const handleDelete = async (id) => {
    if (!window.confirm("Are you absolutely sure you want to permanently delete this assignment? All student submission records will be lost.")) {
      return;
    }

    try {
      const res = await deleteAssignment(id);
      if (res.data?.success) {
        setAssignments(assignments.filter(a => a._id !== id));
        toast.success("Assignment permanently deleted");
      } else {
        toast.error("Failed to delete assignment");
      }
    } catch (err) {
      console.error("Error deleting assignment:", err);
      toast.error("Encountered database delete error");
    }
  };

  // Search Filter
  const filteredAssignments = assignments.filter((a) =>
    a.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (a.courseId?.title || "").toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <motion.div
      initial={{ opacity: 0, y: 15 }}
      animate={{ opacity: 1, y: 0 }}
      className="space-y-8"
      id="teacher-assignment-module-container"
    >
      {/* Header Panel */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 bg-gradient-to-r from-primary/10 via-base-100 to-base-100 p-6 rounded-3xl border border-primary/20 shadow-xl backdrop-blur-md">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <span className="badge badge-primary gap-1 py-3 px-3 rounded-full text-xs font-semibold">
              <Sparkles className="h-3 w-3" /> Teacher Portal
            </span>
          </div>
          <h1 className="text-3xl font-extrabold text-foreground">Assignment Management</h1>
          <p className="text-sm text-muted-foreground">Deliver briefs, compile AI quizzes, and evaluate student workspaces.</p>
        </div>
        <Button
          onClick={() => setShowCreateModal(true)}
          className="flex items-center gap-2 rounded-2xl h-12 px-5 text-white"
          id="create-assignment-trigger"
        >
          <Plus className="h-5 w-5" /> Publish New Brief
        </Button>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        <Card className="border-base-300 shadow-xl hover:shadow-2xl transition-all rounded-3xl bg-base-100">
          <CardContent className="p-6 flex items-center gap-4">
            <div className="p-4 bg-primary/10 text-primary rounded-2xl">
              <ClipboardList className="h-7 w-7" />
            </div>
            <div>
              <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider">Total Assignments</p>
              <h3 className="text-2xl font-extrabold text-foreground">{assignments.length}</h3>
            </div>
          </CardContent>
        </Card>

        <Card className="border-base-300 shadow-xl hover:shadow-2xl transition-all rounded-3xl bg-base-100">
          <CardContent className="p-6 flex items-center gap-4">
            <div className="p-4 bg-success/10 text-success rounded-2xl">
              <FileCheck className="h-7 w-7" />
            </div>
            <div>
              <p className="text-xs font-bold text-muted-foreground uppercase tracking-wider">AI Generated</p>
              <h3 className="text-2xl font-extrabold text-foreground">
                {assignments.filter(a => a.generatedFromDocument).length}
              </h3>
            </div>
          </CardContent>
        </Card>

        <Card className="border-base-300 shadow-xl hover:shadow-2xl transition-all rounded-3xl bg-base-100">
          <CardContent className="p-6 flex items-center gap-4">
            <div className="p-4 bg-secondary/10 text-secondary rounded-2xl">
              <BrainCircuit className="h-7 w-7" />
            </div>
            <div>
