import {
  ArrowLeft,
  Calendar,
  Award,
  Users,
  Clock,
  CheckCircle,
  HelpCircle,
  TrendingUp,
  Sparkles,
  ChevronRight,
  Eye,
} from "lucide-react";
import { getQuizAnalytics } from "../../../services/quizService";
import { Card, CardContent } from "../../../components/ui/Card";
import { Button } from "../../../components/ui/Button";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";
import toast from "react-hot-toast";

const COLORS = ["#EF4444", "#F59E0B", "#3B82F6", "#8B5CF6", "#10B981"];

export default function QuizAnalytics() {
  const { id } = useParams(); // quizId
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [analytics, setAnalytics] = useState(null);

  useEffect(() => {
    async function loadAnalytics() {
      try {
        setLoading(true);
        const res = await getQuizAnalytics(id);
        if (res.data?.success) {
          setAnalytics(res.data.data);
        } else {
          toast.error("Failed to load quiz analytics");
        }
      } catch (err) {
        console.error("Error fetching quiz analytics:", err);
        toast.error("Error preparing quiz metrics calculations");
      } finally {
        setLoading(false);
      }
    }
    loadAnalytics();
  }, [id]);

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[70vh] gap-4" id="quiz-analytics-loading">
        <div className="loading loading-spinner loading-lg text-primary"></div>
        <p className="text-sm text-muted-foreground animate-pulse">Computing scoring aggregates and student leaderboard...</p>
      </div>
